    function qiblaBearing(lat, lon) {
      // Азимут на Каабу (Мекка) от точки (lat, lon), градусы 0–360 от севера по часовой
      const kLat = 21.422487, kLon = 39.826206;
      const φ1 = lat * Math.PI / 180;
      const φ2 = kLat * Math.PI / 180;
      const Δλ = (kLon - lon) * Math.PI / 180;
      const y = Math.sin(Δλ) * Math.cos(φ2);
      const x = Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
      let θ = Math.atan2(y, x) * 180 / Math.PI;
      return ((θ % 360) + 360) % 360;
    }
    // build 5.72: точка на сфере на заданном азимуте и расстоянии от старта —
    // используется для короткой стрелки-направления на карте киблы (не для
    // линии до самой Мекки: на плоской проекции карты прямая линия через
    // тысячи км была бы геометрически неверной для истинного азимута).
    function destinationPoint(lat, lon, bearingDeg, distanceMeters) {
      const R = 6371000;
      const δ = distanceMeters / R;
      const θ = bearingDeg * Math.PI / 180;
      const φ1 = lat * Math.PI / 180;
      const λ1 = lon * Math.PI / 180;
      const φ2 = Math.asin(Math.sin(φ1) * Math.cos(δ) + Math.cos(φ1) * Math.sin(δ) * Math.cos(θ));
      const λ2 = λ1 + Math.atan2(Math.sin(θ) * Math.sin(δ) * Math.cos(φ1), Math.cos(δ) - Math.sin(φ1) * Math.sin(φ2));
      return { lat: φ2 * 180 / Math.PI, lon: λ2 * 180 / Math.PI };
    }
    function fetchAladhanTimes(lat, lon, date, methodKey) {
      const d = date || new Date();
      const dd = String(d.getDate()).padStart(2,'0');
      const mm = String(d.getMonth()+1).padStart(2,'0');
      const yyyy = d.getFullYear();
      const method = ALADHAN_METHOD[methodKey] || 3;
      const school = 1; // ханафитский асыр
      const url = 'https://api.aladhan.com/v1/timings/'+dd+'-'+mm+'-'+yyyy
        + '?latitude='+lat+'&longitude='+lon+'&method='+method+'&school='+school;
      const ctrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
      const t = setTimeout(function(){ try { ctrl && ctrl.abort(); } catch(e){} }, 5000);
      return fetch(url, ctrl ? { signal: ctrl.signal } : undefined)
        .then(function(res){ clearTimeout(t); if (!res.ok) throw new Error('http'); return res.json(); })
        .then(function(data){
          const tm = data && data.data && data.data.timings;
          if (!tm) return null;
          const cut = function(s){ return (s || '').toString().split(' ')[0]; };
          return {
            fajr: cut(tm.Fajr), sunrise: cut(tm.Sunrise), dhuhr: cut(tm.Dhuhr),
            asr: cut(tm.Asr), maghrib: cut(tm.Maghrib), isha: cut(tm.Isha),
            _src: 'aladhan'
          };
        })
        .catch(function(){ clearTimeout(t); return null; });
    }

