    async function upsertMyProfile() {
      var sb = getSb();
      if (!sb) return;
      try {
        var res = await sb.auth.getUser();
        var user = res && res.data && res.data.user;
        if (!user) return;
        var meta = user.user_metadata || {};
        var nick = meta.nick || meta.nickname || (user.email || '').split('@')[0] || 'user';
        await sb.from('profiles').upsert({
          id: user.id,
          nick: nick,
          email: user.email || '',
          created_at: user.created_at || new Date().toISOString(),
          updated_at: new Date().toISOString()
        }, { onConflict: 'id' });
      } catch (e) { console.warn('profile', e); }
    }
    function sumInRange(map, daysBack) {
      // Только реальные ключи дат в map — без умножения «сегодня × число дней»
      if (!map || typeof map !== 'object') return 0;
      var total = 0;
      var now = new Date();
      var todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
      Object.keys(map).forEach(function(k) {
        var val = Number(map[k]);
        if (!val || val !== val) return;
        if (daysBack == null) { total += val; return; }
        var p = String(k).match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (!p) return;
        var t = new Date(+p[1], +p[2] - 1, +p[3]).getTime();
        if (isNaN(t)) return;
        var diff = Math.round((todayStart - t) / 86400000);
        if (diff >= 0 && diff <= daysBack) total += val;
      });
      return total;
    }
    function sumInMonth(map, year, month) {
      if (!map || typeof map !== 'object') return 0;
      var t = 0;
      var prefix = year + '-' + String(month + 1).padStart(2, '0') + '-';
      Object.keys(map).forEach(function(d) {
        if (String(d).indexOf(prefix) === 0) {
          var val = Number(map[d]);
          if (val && val === val) t += val;
        }
      });
      return t;
    }
