// ===== из app-12-online-forum-caches — Вкладка Онлайн, вопросы, форум, общий чат, кэши аудио/слов/картинок/сообщений, лимиты =====
    function getOnlineOrder() {
      var def = ONLINE_ORDER_DEFAULT;
      try {
        var o = JSON.parse(localStorage.getItem('quran_online_order') || 'null');
        if (Array.isArray(o) && o.length) {
          // убрать неизвестные/устаревшие id, добавить в конец новые из def,
          // которых у пользователя ещё нет (тот же приём, что и в getMainTabOrder)
          var ok = o.filter(function(id){ return def.indexOf(id) >= 0; });
          def.forEach(function(id){ if (ok.indexOf(id) < 0) ok.push(id); });
          return ok;
        }
      } catch(e) {}
      return def.slice();
    }
    function saveOnlineOrder(order) {
      try { localStorage.setItem('quran_online_order', JSON.stringify(order)); } catch(e) {}
    }
    // build 4.70: раньше порядок карточек «Онлайн» менялся только из
    // Настроек (стрелки ↑/↓ в блоке «🌐 Онлайн»), а список/сетку выбрать
    // было вообще нельзя — сетка была жёстко зашита. Теперь, как и у «Ещё»,
    // список/сетка и «Изменить порядок» — прямо в самой вкладке «Онлайн»;
    // настройки лишь скрывают отдельные карточки, порядок и раскладку туда
    // больше не дублируем.
    let onlineEditMode = false;
    function getOnlineLayout() {
      try { return localStorage.getItem('quran_online_layout') || 'grid'; } catch(e) { return 'grid'; }
    }
    function saveOnlineLayout(v) {
      try { localStorage.setItem('quran_online_layout', v); } catch(e) {}
    }
    function renderOnlineHub() {
      const el = document.getElementById('online-body');
      if (!el) return;
      const kk = isKk();
      const isAdmin = (typeof isAdminUser === 'function') && isAdminUser();
      // build 6.59: для администратора и модератора — вкладки «Онлайн | Админ» / «Онлайн | Модератор»;
      // обычные пользователи их не видят. Админские карточки переехали с общей сетки в свою вкладку.
      const isStaff = (typeof isStaffUser === 'function') && isStaffUser();
      if (!isStaff) window._onlineTab = 'online';
      const staffTab = isStaff && window._onlineTab === 'staff';
      let items = staffTab
        ? (isAdmin
            ? [{ id: 'registration', icon: '👥', label: 'Регистрация' }, { id: 'stats', icon: '📊', label: kk ? 'Статистика' : 'Статистика' }, { id: 'reports', icon: '🚩', label: 'Жалобы' }, { id: 'moderators', icon: '🛡️', label: kk ? 'Модератор' : 'Модератор' }]
            : [{ id: 'reports', icon: '🛡️', label: kk ? 'Модерация' : 'Модерация' }])
        : MORE_MENU_DEFAULT.filter(function(it) { return it && it.group === 'online'; });
      // build 4.100: «📊 Хранилище» больше не отдельная плитка среди
      // остальных — по просьбе пользователя показывается прямо на главном
      // экране «Онлайн», сразу под подсказкой, чтобы лимит был на виду
      // при каждом заходе, а не только если специально зайти в раздел.
      items = items.filter(function(it){ return it.id !== 'storagelimits' && (staffTab || it.id !== 'stats'); });
      // Тот же принцип, что и в «Ещё»: скрытые пользователем разделы не
      // показываем (можно скрыть, например, «Статистика», если
      // не пользуетесь ими).
      if (!staffTab) {
        try { items = items.filter(function(it){ return it && !isSectionHidden(it.id); }); } catch(e) {}
        const orderHint = getOnlineOrder();
        items.sort(function(a, b){ return orderHint.indexOf(a.id) - orderHint.indexOf(b.id); });
      }

      var tip = tipCard(kk
        ? 'Мұнда — сайттың барлық «онлайн» бөлімдері (тіркелу қажет):<br>' +
          '• 💭 <b>Жалпы чат</b> — барлық қолданушыларға арналған ортақ чат.<br>' +
          '• ✉️ <b>Жеке хабарламалар</b> — біреумен жеке хат-хабар (ЛС).<br>' +
          '• 👥 <b>Топтық чаттар</b> — топ құру/қосылу, ашық топтар тізімі.<br>' +
          '• 🧑‍🤝‍🧑 <b>Достар</b> — достар тізімі, қосу/жою, іздеу.<br>' +
          '• 💬 <b>Форум</b> — сұрақ қою, санаттар бойынша талқылау.<br>' +
          '• ❓ <b>Менің сұрақтарым</b> — өзіңіз білетінге жіберген сұрақтар мен жауаптар.<br>' +
          '• 🔔 <b>Хабарламалар</b> — жаңа хабарлар, сұрақ жауаптары және т.б. туралы ескертулер.<br>' +
          '• Санақ (бейджик) картада — сол бөлімде жаңа/оқылмаған нәрсе бар дегенді білдіреді.<br>' +
          '• Тор/тізім — жоғарыдағы орналасу түймелері; «Реті» — карточкаларды ↑↓←→ жылжыту.'
        : 'Здесь — все «онлайновые» разделы сайта (нужна регистрация):<br>' +
          '• 💭 <b>'+tLabel('Общий чат')+'</b> — единый чат для всех пользователей.<br>' +
          '• ✉️ <b>'+tLabel('Личные сообщения')+'</b> — переписка один на один (ЛС).<br>' +
          '• 👥 <b>Групповые чаты</b> — создать/вступить в группу, список открытых групп.<br>' +
          '• 🧑‍🤝‍🧑 <b>Друзья</b> — список друзей, добавление/удаление, поиск.<br>' +
          '• 💬 <b>Форум</b> — задать вопрос, обсуждение по категориям.<br>' +
          '• ❓ <b>'+tLabel('Мои вопросы/ответы')+'</b> — вопросы знающему и полученные ответы.<br>' +
          '• 🔔 <b>'+tLabel('Уведомления')+'</b> — оповещения о новых сообщениях, ответах и т.п.<br>' +
          '• Значок с числом на карточке — есть что-то новое/непрочитанное в этом разделе.<br>' +
          '• Сетка/список — кнопки раскладки сверху; «Порядок» — двигать карточки ↑↓←→.');

      const layout = getOnlineLayout();
      const cols = layout === 'grid3' ? 3 : (layout === 'grid' ? 2 : 1);
      var html = items.map(function(it, idx) {
        const obCount = it.id === 'notifications'
          ? (typeof _nfUnreadCount === 'function' ? _nfUnreadCount() : 0)
          : (_onlineBadges[it.id] || 0);
        if (layout === 'list') {
          return '<div class="card online-hub-item" data-goto="'+it.id+'" data-idx="'+idx+'" style="position:relative;cursor:pointer">' +
            (obCount > 0 ? '<span class="mini-badge">'+(obCount > 99 ? '99+' : obCount)+'</span>' : '') +
            '<div>'+it.icon+' '+(typeof tLabel==='function'?tLabel(it.label):it.label)+'</div>' +
            ((onlineEditMode && !staffTab) ? '<div class="more-actions dpad">' +
              '<button type="button" class="btn btn-sm" data-oh-up="'+idx+'" title="Вверх">↑</button>' +
              '<button type="button" class="btn btn-sm" data-oh-down="'+idx+'" title="Вниз">↓</button>' +
              '</div>' : '') +
          '</div>';
        }
        // build 4.86: у карточек с длинной подписью (например «Личные
        // сообщения», «Мои вопросы/ответы») текст переносится на 2 строки —
        // блок с иконкой и подписью становится выше, и стрелки внутри такой
        // карточки съезжают ниже, чем у соседей с однострочной подписью в
        // той же строке сетки (у самих карточек высота и так одинаковая —
        // сетка растягивает их по умолчанию, но стрелки внутри просто
        // следуют за текстом, а не прижаты к низу). Теперь карточка — flex-
        // колонка, а стрелки всегда прижаты к низу через margin-top:auto —
        // выравниваются между соседними карточками независимо от длины подписи.
        return '<div class="card online-hub-item" data-goto="'+it.id+'" data-idx="'+idx+'" style="position:relative;text-align:center;cursor:pointer;padding:0.9rem 0.5rem;display:flex;flex-direction:column;align-items:center">' +
          (obCount > 0 ? '<span class="mini-badge">'+(obCount > 99 ? '99+' : obCount)+'</span>' : '') +
          '<div style="font-size:1.7rem">'+it.icon+'</div>' +
          '<div style="margin-top:0.3rem;font-size:0.82rem">'+(typeof tLabel==='function'?tLabel(it.label):it.label)+'</div>' +
          ((onlineEditMode && !staffTab) ? '<div class="more-actions dpad" style="margin-top:auto;padding-top:0.35rem">' +
            '<button type="button" class="btn btn-sm" data-oh-up="'+idx+'" title="Вверх">↑</button>' +
            '<button type="button" class="btn btn-sm" data-oh-left="'+idx+'" title="Влево">←</button>' +
            '<button type="button" class="btn btn-sm" data-oh-down="'+idx+'" title="Вниз">↓</button>' +
            '<button type="button" class="btn btn-sm" data-oh-right="'+idx+'" title="Вправо">→</button>' +
            '</div>' : '') +
        '</div>';
      }).join('');

      el.className = layout === 'grid' ? 'more-grid' : (layout === 'grid3' ? 'more-grid-3' : '');
      // build 6.75: плитки по группам (кроме режима «Порядок» и админ-вкладки)
      const gridCls = el.className;
      if (!staffTab && !onlineEditMode) {
        const ONLINE_GROUPS = [
          { ru: '💬 Общение', kk: '💬 Қарым-қатынас', ids: ['dmlist', 'publicchat', 'groups', 'friends'] },
          { ru: '📚 Знания', kk: '📚 Білім', ids: ['forum', 'myqa', 'ask', 'usersearch', 'chatsearch'] },
          { ru: '👤 Я', kk: '👤 Мен', ids: ['account', 'notifications'] },
          { ru: '🛠 Сайт', kk: '🛠 Сайт', ids: ['feedback', 'myreports', 'blockedlist', 'reports', 'registration'] }
        ];
        const cards = html.split('<div class="card online-hub-item"').slice(1).map(function (c) { return '<div class="card online-hub-item"' + c; });
        const byId = {}; items.forEach(function (it, i) { byId[it.id] = cards[i]; });
        const used = {};
        html = ONLINE_GROUPS.map(function (g) {
          const part = items.filter(function (it) { return g.ids.indexOf(it.id) >= 0; }).map(function (it) { used[it.id] = 1; return byId[it.id]; }).join('');
          return part ? '<div class="online-group-title">' + (kk ? g.kk : g.ru) + '</div><div class="' + gridCls + '">' + part + '</div>' : '';
        }).join('');
        const rest = items.filter(function (it) { return !used[it.id]; }).map(function (it) { return byId[it.id]; }).join('');
        if (rest) html += '<div class="online-group-title">' + (kk ? '➕ Тағы' : '➕ Ещё') + '</div><div class="' + gridCls + '">' + rest + '</div>';
        el.className = '';
      }
      // build 5.48: раньше «график» (виджет с полосками лимитов) был
      // пустым div-ом до тех пор, пока не отработают сетевые запросы —
      // на фоне остальных карточек (они рисуются сразу, синхронно) это
      // выглядело так, будто именно виджет лимитов «открывается позже».
      // Теперь сама карточка со всеми 4 полосками рисуется сразу
      // (со скелетоном вместо цифр), а настоящие цифры лимитов
      // подставляются в неё уже после загрузки — без пустого места.
      var staffTabsHtml = '';
      if (isStaff) {
        var staffLab = isAdmin ? (kk ? 'Әкімші' : 'Админ') : (kk ? 'Модератор' : 'Модератор');
        staffTabsHtml = '<div class="more-tip-wrap"><div style="display:flex;gap:0.4rem;margin-bottom:0.6rem">' +
          [['online', kk ? 'Онлайн' : 'Онлайн'], ['staff', staffLab]].map(function(t) {
            var a = (staffTab ? 'staff' : 'online') === t[0];
            return '<button type="button" class="btn btn-sm online-staff-tab" data-ot="' + t[0] + '" style="flex:1;' + (a ? 'background:var(--accent);color:#04120c;border-color:var(--accent)' : '') + '">' + (t[0] === 'staff' ? '🛡 ' : '🌐 ') + t[1] + '</button>';
          }).join('') + '</div></div>';
      }
      if (staffTab) {
        el.innerHTML = staffTabsHtml + '<div class="more-tip-wrap">' + tipCard(isAdmin
          ? (kk ? 'Әкімші бөлімдері: тіркелгендер, шағымдар (және сүзгі белгілері), модераторларды тағайындау.' : 'Разделы администратора: регистрации, жалобы (и отметки фильтра), назначение модераторов.')
          : (kk ? 'Модератор бөлімі: тексеруге түскен хабарламалар мен шағымдар. Бан беру және ұпайларды көру тек әкімшіде.' : 'Раздел модератора: сообщения на проверке и жалобы. Бан и очки — только у администратора.')) + '</div>' + html;
      } else {
        // build 6.75: сверху — профиль со счётчиками или приглашение войти
        let topCard = '';
        try {
          const sess = (typeof authSession === 'function') ? authSession() : null;
          const nick = sess && (sess.nick || (sess.email || '').split('@')[0]);
          if (nick) {
            const nN = (typeof _nfUnreadCount === 'function' ? _nfUnreadCount() : 0) || 0, dN = _onlineBadges.dmlist || 0, cN = _onlineBadges.publicchat || 0, gN = _onlineBadges.groups || 0;
            const chip = function (id, ic, n, lb) { return '<button type="button" class="online-chip" data-goto="' + id + '">' + ic + ' ' + lb + (n ? ' <b>' + (n > 99 ? '99+' : n) + '</b>' : '') + '</button>'; };
            topCard = '<div class="card online-me">' +
              '<div class="online-me-row" data-goto="account"><span class="online-ava">' + fsEsc(String(nick).slice(0, 1).toUpperCase()) + '</span><span style="flex:1;min-width:0"><b>' + fsEsc(nick) + '</b><div style="font-size:0.78rem;color:var(--text-muted)">' + (kk ? 'Менің аккаунтым →' : 'Мой аккаунт →') + '</div></span></div>' +
              '<div class="online-me-chips">' + chip('notifications', '🔔', nN, kk ? 'Хабарлар' : 'Уведомления') + chip('dmlist', '✉️', dN, kk ? 'ЛС' : 'ЛС') + chip('publicchat', '💭', cN, kk ? 'Чат' : 'Чат') + chip('groups', '👥', gN, kk ? 'Топтар' : 'Группы') + '</div></div>';
          } else {
            topCard = '<div class="card online-guest"><b>🌐 ' + (kk ? 'Онлайн-қауымдастық' : 'Онлайн-сообщество') + '</b>' +
              '<div class="ayah-translation" style="margin-top:0.3rem">' + (kk ? 'Кірсеңіз: прогресс барлық құрылғыда сақталады, білетіндерге сұрақ қоясыз, форумда талқылайсыз, достармен және топпен бірге Құран оқисыз.' : 'Войдите, чтобы прогресс сохранялся на всех устройствах, задавать вопросы знающим, обсуждать на форуме и читать Коран вместе с друзьями и группой.') + '</div>' +
              '<button type="button" class="btn btn-primary" data-goto="account" style="width:100%;margin-top:0.6rem">' + (kk ? 'Кіру / Тіркелу' : 'Войти / Регистрация') + '</button></div>';
          }
        } catch (e) {}
        el.innerHTML = staffTabsHtml + topCard + '<div class="more-tip-wrap">' + tip + '</div>' + '<div id="online-storage-widget">' + _onlineStorageWidgetSkeleton(kk) + '</div>' + html;
        el.querySelectorAll('.online-me [data-goto], .online-guest [data-goto]').forEach(function (b) { b.addEventListener('click', function () { showView(b.getAttribute('data-goto')); }); });
        _renderOnlineStorageWidget(kk);
      }
      el.querySelectorAll('.online-staff-tab').forEach(function(b) {
        b.addEventListener('click', function() { window._onlineTab = b.getAttribute('data-ot'); renderOnlineHub(); });
      });
      // роль могла измениться после входа (админ назначил) — тихо перечитываем и перерисовываем один раз
      if (!window._staffRoleChecked && typeof _refreshMyAdminFlag === 'function') {
        window._staffRoleChecked = true;
        var wasStaff = isStaff;
        _refreshMyAdminFlag().then(function() { if ((typeof isStaffUser === 'function' && isStaffUser()) !== wasStaff) renderOnlineHub(); }).catch(function() {});
      }
      // build 4.100: автообновление лимитов — каждую минуту, пока открыт
      // именно этот экран (лёгкий агрегатный запрос, для 10 человек и
      // объёма данных чата это не создаёт заметной нагрузки). Старый
      // интервал (если экран открывали раньше) всегда чистится первым —
      // иначе при повторных заходах в «Онлайн» они бы копились и слали
      // всё больше параллельных запросов одновременно.
      clearInterval(window._onlineStorageWidgetTimer);
      window._onlineStorageWidgetTimer = setInterval(function() {
        if (!document.getElementById('online-storage-widget')) { clearInterval(window._onlineStorageWidgetTimer); return; }
        _renderOnlineStorageWidget(kk);
      }, 60000);

      document.getElementById('online-layout-list')?.classList.toggle('btn-primary', layout === 'list');
      document.getElementById('online-layout-grid')?.classList.toggle('btn-primary', layout === 'grid');
      document.getElementById('online-layout-grid3')?.classList.toggle('btn-primary', layout === 'grid3');
      const editBtn = document.getElementById('online-edit-order');
      if (editBtn) editBtn.style.display = staffTab ? 'none' : '';
      if (editBtn) editBtn.textContent = onlineEditMode ? (kk ? 'Дайын' : 'Готово') : (kk ? 'Реті' : 'Порядок');
      const hint = document.getElementById('online-edit-hint');
      if (hint) hint.style.display = onlineEditMode ? 'block' : 'none';
      document.body.classList.toggle('online-editing', onlineEditMode);

      const moveItem = (from, to) => {
        const order = getOnlineOrder();
        // items может быть отфильтрован (скрытые разделы) — двигаем внутри
        // полного списка order, найдя реальные id по текущим items.
        const idFrom = items[from] && items[from].id;
        const idTo = items[to] && items[to].id;
        if (!idFrom || !idTo) return;
        const iFrom = order.indexOf(idFrom);
        const iTo = order.indexOf(idTo);
        if (iFrom < 0 || iTo < 0 || iFrom === iTo) return;
        const [x] = order.splice(iFrom, 1);
        order.splice(iTo, 0, x);
        saveOnlineOrder(order);
        renderOnlineHub();
      };
      el.querySelectorAll('[data-oh-up]').forEach(b => b.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = +b.dataset.ohUp;
        moveItem(i, i - cols);
      }));
      el.querySelectorAll('[data-oh-down]').forEach(b => b.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = +b.dataset.ohDown;
        moveItem(i, i + cols);
      }));
      el.querySelectorAll('[data-oh-left]').forEach(b => b.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = +b.dataset.ohLeft;
        if (cols > 1 && i % cols === 0) return;
        moveItem(i, i - 1);
      }));
      el.querySelectorAll('[data-oh-right]').forEach(b => b.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = +b.dataset.ohRight;
        if (cols > 1 && i % cols === cols - 1) return;
        moveItem(i, i + 1);
      }));

      el.querySelectorAll('.online-hub-item').forEach(function(card) {
        card.addEventListener('click', function(ev) {
          if (onlineEditMode) return;
          if (ev.target.closest('[data-oh-up],[data-oh-down],[data-oh-left],[data-oh-right]')) return;
          const id = card.getAttribute('data-goto');
          if (id === 'moderators') { window._reportsTab = 'moderators'; showView('reports'); return; }
          if (id === 'reports' && window._reportsTab === 'moderators') window._reportsTab = 'new';
          if (id) showView(id);
        });
      });
      // build 5.37: реальный баг — с build 4.100 плитка «📊 Хранилище»
      // убрана из общего списка (см. комментарий выше, items.filter
      // it.id !== 'storagelimits'), а сам компактный виджет на главном
      // экране «Онлайн» никуда не вёл. При этом полноценный экран
      // «Хранилище» (renderStorageLimits, с подробными пояснениями и
      // официальными лимитами тарифа) остался в коде рабочим, но
      // открыть его стало неоткуда — ни одна кнопка интерфейса на него
      // больше не ссылалась. Теперь клик по самому виджету открывает
      // этот полноценный экран.
      var storageWidgetEl = document.getElementById('online-storage-widget');
      if (storageWidgetEl) {
        storageWidgetEl.style.cursor = 'pointer';
        storageWidgetEl.addEventListener('click', function() {
          if (onlineEditMode) return;
          if (storageWidgetEl.getAttribute('data-has-widget') !== '1') return; // гость/офлайн/ошибка — нажимать некуда
          showView('storagelimits');
        });
      }
    }
    document.getElementById('online-layout-list')?.addEventListener('click', () => { saveOnlineLayout('list'); renderOnlineHub(); });
    document.getElementById('online-layout-grid')?.addEventListener('click', () => { saveOnlineLayout('grid'); renderOnlineHub(); });
    document.getElementById('online-layout-grid3')?.addEventListener('click', () => { saveOnlineLayout('grid3'); renderOnlineHub(); });
    document.getElementById('online-edit-order')?.addEventListener('click', () => { onlineEditMode = !onlineEditMode; renderOnlineHub(); });
    function renderOnlinePlaceholder(id, title) {
      const el = document.getElementById(id + '-body');
      if (!el) return;
      const tip = (typeof t === 'function') ? t('online_soon_tip') : 'Раздел в разработке. Скоро появятся онлайн-функции.';
      el.innerHTML =
        '<p class="ayah-translation" style="margin:0 0 0.6rem">' + tip + '</p>' +
        '<div class="empty-state"><p>' + ((typeof t==='function')?t('online_empty'):'Пока пусто') + '</p></div>';
      try { bindTipToggles(el, id); } catch(e) {}
    }
    // ===== Мои вопросы/ответы: публичный/анонимный Q&A с учителями =====
    function qaGenderLabel(g, kk) {
      if (g === 'male') return kk ? 'Ер' : 'Муж.';
      if (g === 'female') return kk ? 'Әйел' : 'Жен.';
      return '';
    }
    function qaMazhabLabel(m, kk) {
      var map = {
        hanafi: 'Ханафи',
        shafii: kk ? 'Шафиғи' : 'Шафии',
        maliki: 'Малики',
        hanbali: 'Ханбали',
        other: kk ? 'Басқа/жоқ' : 'Другой/нет'
      };
      return map[m] || '';
    }
    // opts.allowAnswer — показывать ли кнопку «Ответить» (решает вызывающий код —
    //   он знает, учитель ли это и в каком разделе показывается карточка);
    // opts.allowDelete — показывать ли кнопку «Удалить» (дополнительно требуется mine).
    // opts.isAdmin — показывать ли администраторские кнопки: «Удалить вопрос полностью»
    //   (доступна всегда, даже если вопрос отвечен и не свой) и «Удалить только ответ»
    //   (доступна, если есть ответ) — не требуют mine, в отличие от обычной «Удалить».
    // Раньше право отвечать определялось прямо здесь через isTeacher, и это же
    // право автоматически действовало и в «Мои вопросы/ответы», и на «Форуме» —
    // теперь у каждого раздела свои правила видимости/прав, поэтому они передаются явно.
    function renderQaCard(q, sess, kk, opts) {
      opts = opts || {};
      var mine = !!(sess && q.user_id === sess.userId);
      var authorLabel = q.is_anonymous
        ? (kk ? 'Аноним' : 'Аноним')
        : (String(q.nick || '').replace(/</g,'&lt;') || (kk ? 'Қолданушы' : 'Пользователь'));
      var details = [];
      if (q.age) details.push((kk ? 'Жасы: ' : 'Возраст: ') + parseInt(q.age,10));
      var gl = qaGenderLabel(q.gender, kk); if (gl) details.push(gl);
      if (q.country) details.push(String(q.country).replace(/</g,'&lt;'));
      var ml = qaMazhabLabel(q.mazhab, kk); if (ml) details.push(ml);
      var detailsLine = details.length ? '<div style="font-size:0.78rem;color:var(--text-muted);margin-top:0.15rem">'+details.join(' · ')+'</div>' : '';
      var extraLine = q.extra_text ? '<div class="ayah-translation" style="margin-top:0.3rem;font-size:calc(0.85rem * var(--ru-scale, 1))">'+String(q.extra_text).replace(/</g,'&lt;')+'</div>' : '';
      // Если вопрос скрыт админом (hidden_by_admin) — показываем отдельный, более
      // «тревожный» значок вместо обычного «анонимно», чтобы было видно, что это не
      // сам автор выбрал анонимность, а решение администратора (обычно — слишком
      // простой/неважный вопрос, чтобы тратить на него общее внимание на Форуме).
      var anonBadge = q.hidden_by_admin
        ? ' <span style="font-size:0.72rem;color:var(--danger)">🛡'+(kk?' әкімші жасырды':' скрыто админом')+'</span>'
        : (q.is_anonymous ? ' <span style="font-size:0.72rem;color:var(--warning)">🔒'+(kk?' анонимды':' анонимно')+'</span>' : '');
      // build 4.52: тема (категория) вопроса — тот же список, что и фильтр в Форуме.
      var catLabel = q.category ? qaCategoryLabel(q.category, kk) : null;
      var catBadge = catLabel ? ' <span style="font-size:0.72rem;color:var(--text-muted);border:1px solid var(--border);border-radius:0.3rem;padding:0.02rem 0.35rem">'+catLabel+'</span>' : '';
      var answerBlock = q.answer_text
        ? '<div class="card" style="margin-top:0.5rem;background:var(--bg);border-color:var(--accent)"><b style="color:var(--accent)">'+(kk?'Жауап':'Ответ')+'</b><div class="ayah-translation" style="margin-top:0.25rem;white-space:pre-wrap">'+String(q.answer_text).replace(/</g,'&lt;')+'</div></div>'
        : '<div style="font-size:0.8rem;color:var(--text-muted);margin-top:0.4rem">'+(kk?'Жауап әлі жоқ':'Ответа пока нет')+'</div>';
      // !mine — если вопрос задал сам учитель, кнопки «Ответить» на своей же
      // карточке быть не должно: учитель не может отвечать сам себе на форуме.
      var answerFormBtn = (opts.allowAnswer && !q.answer_text && !mine)
        ? '<button type="button" class="btn btn-sm" data-qa-answer="'+q.id+'" style="width:100%;margin-top:0.4rem">'+(kk?'Жауап беру':'Ответить')+'</button>'
        : '';
      var delBtn = (opts.allowDelete && mine && !q.answer_text)
        ? '<button type="button" class="btn btn-sm" data-qa-del="'+q.id+'" style="width:100%;margin-top:0.35rem;color:var(--danger)">'+(kk?'Жою':'Удалить')+'</button>'
        : '';
      // Кнопки администратора: работают для ЛЮБОГО вопроса (не только своего) и
      // независимо от того, есть ли уже ответ. Требуют на стороне Supabase RLS-
      // политик DELETE/UPDATE для админ-аккаунтов на таблице questions — без них
      // сервер вернёт "permission denied", несмотря на то что кнопка видна в UI
      // (сама по себе проверка ADMIN_EMAILS — это только UI-ограничение).
      var adminDelFullBtn = opts.isAdmin
        ? '<button type="button" class="btn btn-sm" data-qa-admin-del-full="'+q.id+'" style="width:100%;margin-top:0.35rem;color:var(--danger)">🛡 '+(kk?'Сұрақты толық жою (админ)':'Удалить вопрос полностью (админ)')+'</button>'
        : '';
      var adminDelAnswerBtn = (opts.isAdmin && q.answer_text)
        ? '<button type="button" class="btn btn-sm" data-qa-admin-del-answer="'+q.id+'" style="width:100%;margin-top:0.35rem;color:var(--warning)">🛡 '+(kk?'Тек жауапты жою (админ)':'Удалить только ответ (админ)')+'</button>'
        : '';
      // Админ: скрыть/показать вопрос вручную — не удаляя его, а лишь ограничивая
      // видимость до учителей (тем же способом, что и обычная авторская анонимность),
      // например когда вопрос слишком лёгкий/неважный, чтобы остальные тратили на
      // него время. hidden_by_admin — отдельный флаг именно для этого значка/кнопки,
      // отличающий решение админа от анонимности, выбранной самим автором вопроса.
      var adminHideBtn = (opts.isAdmin && !q.hidden_by_admin)
        ? '<button type="button" class="btn btn-sm" data-qa-admin-hide="'+q.id+'" style="width:100%;margin-top:0.35rem;color:var(--warning)">🛡 '+(kk?'Барлығынан жасыру (жеңіл сұрақ)':'Скрыть от всех (лёгкий вопрос)')+'</button>'
        : '';
      var adminUnhideBtn = (opts.isAdmin && q.hidden_by_admin)
        ? '<button type="button" class="btn btn-sm" data-qa-admin-unhide="'+q.id+'" style="width:100%;margin-top:0.35rem;color:var(--accent)">🛡 '+(kk?'Барлығына қайта көрсету':'Показать всем снова')+'</button>'
        : '';

      // ---- build 4.39/4.46: статус проверки ответа учителями + обсуждение ----
      var isAnswerer = !!(sess && q.answered_by && q.answered_by === sess.userId);
      var isTeacherViewer = !!(opts.allowAnswer);
      var alreadyVoted = !!(opts.myVotedIds && opts.myVotedIds.has(q.id));
      var discussionBlock = '';
      if (q.answer_text) {
        var statusBadge = q.answer_confirmed
          ? '<span style="color:var(--success);font-size:0.75rem">✅ '+(kk?'Тексерілді':'Проверено')+'</span>'
          : '<span style="color:var(--warning);font-size:0.75rem">🕐 '+(kk?'Тексерілмеген':'Не проверено')+'</span>';
        var confirmBtns = '';
        // Подтверждать/оспаривать может учитель, который сам не отвечал на этот
        // вопрос (иначе он мог бы сам себе «подтвердить» ответ) и который ещё
        // не голосовал по этому же ответу (build 4.46) — раньше можно было
        // нажимать «Согласен»/«Не согласен» сколько угодно раз, и в
        // комментариях от одного и того же учителя копилось по несколько
        // голосов подряд (на итоговый счёт они и раньше не влияли — там уже
        // стоял подсчёт по различным user_id — но выглядело так, будто их
        // несколько, и ничто не мешало просто щёлкать кнопку заново).
        if (isTeacherViewer && !isAnswerer && !alreadyVoted) {
          confirmBtns =
            '<button type="button" class="btn btn-sm qa-confirm-btn" data-id="'+q.id+'" style="flex-shrink:0;color:var(--success)">✅ '+(kk?'Растаймын':'Согласен')+'</button>' +
            '<button type="button" class="btn btn-sm qa-dispute-btn" data-id="'+q.id+'" style="flex-shrink:0;color:var(--danger)">❌ '+(kk?'Келіспеймін':'Не согласен')+'</button>';
        } else if (isTeacherViewer && !isAnswerer && alreadyVoted) {
          confirmBtns = '<span style="font-size:0.75rem;color:var(--text-muted)">'+(kk?'Сіз дауыс бердіңіз':'Вы уже проголосовали')+'</span>';
        }
        // build 4.46: 2+ «не согласен» от разных учителей — вопрос с ответом
        // сам собой попадает на заметку админу, без отдельной жалобы.
        var disputeFlagBadge = q.dispute_flagged
          ? '<div style="margin-top:0.35rem;font-size:0.78rem;color:var(--danger);background:var(--bg);border:1px solid var(--danger);border-radius:0.4rem;padding:0.3rem 0.5rem">⚠️ '+(kk?'Бірнеше мұғалім келіспеді — әкімшінің тексеруін күтеді':'Несколько учителей не согласны — ждёт проверки админом')+'</div>'
          : '';
        var adminClearFlagBtn = (opts.isAdmin && q.dispute_flagged)
          ? '<button type="button" class="btn btn-sm qa-admin-clearflag" data-id="'+q.id+'" style="width:100%;margin-top:0.35rem;color:var(--accent)">🛡 '+(kk?'«Тексеру керек» белгісін алып тастау':'Снять пометку «требует проверки»')+'</button>'
          : '';
        discussionBlock =
          '<div style="display:flex;justify-content:space-between;align-items:center;gap:0.4rem;margin-top:0.4rem;flex-wrap:wrap">' +
            statusBadge +
            '<span style="display:flex;gap:0.35rem;flex-wrap:wrap">' + confirmBtns + '</span>' +
          '</div>' +
          disputeFlagBadge + adminClearFlagBtn +
          '<button type="button" class="btn btn-sm qa-discuss-toggle" data-id="'+q.id+'" style="width:100%;margin-top:0.35rem">💬 '+(kk?'Пікірлер: ':'Комментарии: ')+(q.comment_count||0)+'</button>' +
          '<div class="qa-discuss-body" data-discuss-for="'+q.id+'" style="display:none;margin-top:0.4rem"></div>';
      }

      // ---- Жалобы на форуме (build 4.39) ----
      var reportQBtn = !mine
        ? '<button type="button" class="btn btn-sm qa-report-q" data-id="'+q.id+'" data-uid="'+_chatEsc(q.user_id||'')+'" style="width:100%;margin-top:0.35rem;color:var(--text-muted)">🚩 '+(kk?'Сұраққа шағым':'Пожаловаться на вопрос')+'</button>'
        : '';
      var reportABtn = (q.answer_text && !isAnswerer)
        ? '<button type="button" class="btn btn-sm qa-report-a" data-id="'+q.id+'" data-uid="'+_chatEsc(q.answered_by||'')+'" style="width:100%;margin-top:0.35rem;color:var(--text-muted)">🚩 '+(kk?'Жауапқа шағым':'Пожаловаться на ответ')+'</button>'
        : '';

      // ---- Дополнительные действия админа прямо с форума (build 4.39):
      // заблокировать автора вопроса, лишить учителя права отвечать
      // навсегда (принудительно и необратимо переводит в ученики), забанить
      // автора вопроса на отправку новых вопросов на время. ----
      // Кнопки против автора вопроса/ответа скрываются, если этот автор — сам
      // администратор (нельзя заблокировать/забанить/лишить прав самого себя).
      var adminForumBtns = '';
      if (opts.isAdmin) {
        if (!mine) {
          adminForumBtns +=
            '<button type="button" class="btn btn-sm qa-admin-block" data-uid="'+_chatEsc(q.user_id||'')+'" style="width:100%;margin-top:0.35rem;color:var(--danger)">🛡 '+(kk?'Сұрақ авторын бұғаттау':'Заблокировать автора вопроса')+'</button>' +
            '<div style="display:flex;gap:0.3rem;align-items:center;flex-wrap:wrap;margin-top:0.35rem">' +
              '<select class="qa-ban-duration" data-forid="'+q.id+'" style="font-size:0.78rem;padding:0.3rem 0.4rem;border-radius:0.4rem;border:1px solid var(--border);background:var(--bg);color:var(--text)">' +
                [['1h','1 '+(kk?'сағ':'ч')],['3h','3 '+(kk?'сағ':'ч')],['5h','5 '+(kk?'сағ':'ч')],['10h','10 '+(kk?'сағ':'ч')],['1d','1 '+(kk?'күн':'дн')],['3d','3 '+(kk?'күн':'дн')],['5d','5 '+(kk?'күн':'дн')],['10d','10 '+(kk?'күн':'дн')]]
                  .map(function(o){ return '<option value="'+o[0]+'">'+o[1]+'</option>'; }).join('') +
              '</select>' +
              '<button type="button" class="btn btn-sm qa-admin-banask" data-uid="'+_chatEsc(q.user_id||'')+'" data-id="'+q.id+'" style="flex-shrink:0;color:var(--warning)">⏱ '+(kk?'Форумда сұрақ жіберуден бан':'Забанить от вопросов на форуме')+'</button>' +
            '</div>';
        }
        if (q.answered_by && !isAnswerer) {
          adminForumBtns += '<button type="button" class="btn btn-sm qa-admin-demote" data-uid="'+_chatEsc(q.answered_by)+'" style="width:100%;margin-top:0.35rem;color:var(--danger)">🛡 '+(kk?'Мұғалім болу құқығынан мәңгі айыру':'Навсегда лишить права быть учителем')+'</button>';
        }
      }

      return '<div class="card" data-qa-id="'+q.id+'">' +
        '<div style="font-size:0.8rem;color:var(--text-muted)">'+authorLabel+anonBadge+catBadge+(mine?(' · '+(kk?'сіздің сұрағыңыз':'ваш вопрос')):'')+'</div>' +
        detailsLine +
        '<div style="margin-top:0.4rem;white-space:pre-wrap">'+String(q.question_text||'').replace(/</g,'&lt;')+'</div>' +
        extraLine +
        answerBlock +
        discussionBlock +
        answerFormBtn + delBtn + reportQBtn + reportABtn + adminDelAnswerBtn + adminDelFullBtn + adminHideBtn + adminUnhideBtn + adminForumBtns +
        '</div>';
    }
    // reloadFn — что вызывать после успешного действия (у «Мои вопросы/ответы» и «Форума»
    // разные функции перезагрузки, поэтому она передаётся вызывающим кодом, а не жёстко
    // зашита в renderMyQA).
    // ---- build 4.39: обсуждение под ответом (комментарии + подтверждения/
    // несогласия учителей). Комментарий может оставить кто угодно, кому
    // виден сам вопрос (в т.ч. автор — чтобы уточнить у учителя); ставить
    // «Согласен/Не согласен» может только учитель, и не на свой же ответ —
    // это отдельно проверяется и на сервере (см. SQL в чате с пользователем).
    async function renderQaDiscussion(qid, container, kk) {
      container.innerHTML = '<p class="ayah-translation" style="font-size:calc(0.82rem * var(--ru-scale, 1))">'+(kk?'Жүктелуде...':'Загрузка...')+'</p>';
      var sb = getSb();
      if (!sb) return;
      var res = await sb.from('qa_comments').select('*').eq('question_id', qid).order('created_at', { ascending: true });
      if (res && res.error) {
        container.innerHTML = '<p style="color:var(--danger);font-size:0.8rem">'+(kk?'Қате: ':'Ошибка: ')+(res.error.message||'')+'</p>';
        return;
      }
      var rows = (res && res.data) || [];
      var listHtml = rows.map(function(c) {
        var stanceBadge = c.stance === 'confirm'
          ? '<span style="color:var(--success);font-size:0.72rem">✅ '+(kk?'растайды':'согласен')+'</span>'
          : c.stance === 'dispute'
            ? '<span style="color:var(--danger);font-size:0.72rem">❌ '+(kk?'келіспейді':'не согласен')+'</span>'
            : '';
        return '<div style="padding:0.4rem 0;border-top:1px solid var(--border)">' +
          '<div style="font-size:0.75rem;color:var(--text-muted);display:flex;justify-content:space-between;gap:0.4rem"><b style="color:var(--text)">'+_chatEsc(c.nick||'???')+'</b>'+stanceBadge+'</div>' +
          (c.text ? '<div style="font-size:0.85rem;margin-top:0.15rem;white-space:pre-wrap">'+_chatEsc(c.text)+'</div>' : '') +
        '</div>';
      }).join('') || '<p class="ayah-translation" style="font-size:calc(0.8rem * var(--ru-scale, 1))">'+(kk?'Пікірлер жоқ әлі.':'Комментариев пока нет.')+'</p>';

      container.innerHTML = listHtml +
        '<div style="margin-top:0.45rem">' +
          '<textarea class="qa-comment-input" rows="2" style="'+authFormStyle()+'resize:vertical" placeholder="'+(kk?'Түсіндіру/сұрақ...':'Уточнение или вопрос...')+'"></textarea>' +
          '<button type="button" class="btn btn-sm qa-comment-submit" data-id="'+qid+'" style="width:100%;margin-top:0.3rem">'+(kk?'Жіберу':'Отправить')+'</button>' +
        '</div>';

      var submitBtn = container.querySelector('.qa-comment-submit');
      if (submitBtn) submitBtn.addEventListener('click', async function() {
        var ta = container.querySelector('.qa-comment-input');
        var txt = (ta.value || '').trim();
        if (!txt) { toast(kk?'Мәтін жазыңыз':'Напишите текст'); return; }
        var sess = authSession();
        if (!sess) return;
        submitBtn.disabled = true;
        try {
          var ires = await sb.from('qa_comments').insert({ question_id: qid, user_id: sess.userId, nick: sess.nick, text: txt });
          if (ires && ires.error) { toast((kk?'Қате: ':'Ошибка: ')+(ires.error.message||'')); submitBtn.disabled = false; return; }
          renderQaDiscussion(qid, container, kk);
        } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); submitBtn.disabled = false; }
      });
    }
    function bindQaAnswerButtons(wrap, kk, reloadFn) {
      wrap.querySelectorAll('[data-qa-answer]').forEach(function(btn){
        btn.addEventListener('click', function() {
          var id = btn.getAttribute('data-qa-answer');
          var card = wrap.querySelector('[data-qa-id="'+id+'"]');
          if (!card || card.querySelector('.qa-answer-form')) return;
          btn.style.display = 'none';
          var form = document.createElement('div');
          form.className = 'qa-answer-form';
          form.style.marginTop = '0.4rem';
          form.innerHTML =
            '<textarea rows="3" style="'+authFormStyle()+'resize:vertical" placeholder="'+(kk?'Жауабыңыз...':'Ваш ответ...')+'"></textarea>' +
            '<button type="button" class="btn btn-primary btn-sm" style="width:100%">'+(kk?'Сақтау':'Сохранить')+'</button>';
          card.appendChild(form);
          form.querySelector('button').addEventListener('click', async function() {
            var txt = (form.querySelector('textarea').value || '').trim();
            if (!txt) { toast(kk?'Жауапты жазыңыз':'Напишите ответ'); return; }
            var sb = getSb(); var sess = authSession();
            if (!sb || !sess) return;
            try {
              var chk = await sb.auth.getUser();
              if (!(chk && chk.data && chk.data.user)) {
                toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
                if (reloadFn) reloadFn();
                return;
              }
              // .select() в конце обязателен: без него Supabase при успешном запросе,
              // но заблокированном RLS-политикой UPDATE (например, «отвечать может
              // только автор вопроса», из-за чего учитель не может ответить на чужой
              // вопрос), молча обновит 0 строк и НЕ вернёт ошибку — раньше это
              // выглядело как «ответ сохранён», хотя в базе ничего не менялось.
              // С .select() мы видим, что реально вернулось, и можем это проверить.
              var res = await sb.from('questions').update({
                answer_text: txt, answered_by: sess.userId, answered_at: new Date().toISOString()
              }).eq('id', id).select();
              if (res && res.error) {
                if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
                  toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
                  if (reloadFn) reloadFn();
                } else {
                  toast(res.error.message || (kk?'Қате':'Ошибка'));
                }
                return;
              }
              if (!res || !res.data || !res.data.length) {
                // Ошибки нет, но ни одна строка не обновилась — почти всегда это
                // RLS-политика UPDATE в Supabase, которая не разрешает эту запись.
                toast(kk
                  ? 'Жауап сақталмады: құқық жетіспейді (Supabase-те questions кестесінің UPDATE саясатын тексеріңіз)'
                  : 'Ответ не сохранился: не хватает прав (проверьте RLS-политику UPDATE для таблицы questions в Supabase)');
                return;
              }
              toast(kk?'Жауап сақталды':'Ответ сохранён');
              if (reloadFn) reloadFn();
            } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
          });
        });
      });
      wrap.querySelectorAll('[data-qa-del]').forEach(function(btn){
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-qa-del');
          if (!confirm(kk?'Сұрақты жою керек пе?':'Удалить вопрос?')) return;
          var sb = getSb();
          if (!sb) return;
          try {
            var chk = await sb.auth.getUser();
            if (!(chk && chk.data && chk.data.user)) {
              toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
              if (reloadFn) reloadFn();
              return;
            }
            var res = await sb.from('questions').delete().eq('id', id);
            if (res && res.error) {
              if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
                toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
                if (reloadFn) reloadFn();
              } else {
                toast(res.error.message || (kk?'Қате':'Ошибка'));
              }
              return;
            }
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
        });
      });
      // Админ: удалить вопрос целиком (вместе с ответом, если он есть) — не требует mine.
      wrap.querySelectorAll('[data-qa-admin-del-full]').forEach(function(btn){
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-qa-admin-del-full');
          if (!confirm(kk?'Сұрақты (әкімші ретінде) толық жою керек пе? Бұл әрекетті қайтару мүмкін емес.':'Удалить вопрос полностью (как администратор)? Действие необратимо.')) return;
          var sb = getSb();
          if (!sb) return;
          try {
            var chk = await sb.auth.getUser();
            if (!(chk && chk.data && chk.data.user)) {
              toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
              if (reloadFn) reloadFn();
              return;
            }
            var res = await sb.from('questions').delete().eq('id', id).select();
            if (res && res.error) {
              if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
                toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
                if (reloadFn) reloadFn();
              } else {
                toast(res.error.message || (kk?'Қате':'Ошибка'));
              }
              return;
            }
            if (!res || !res.data || !res.data.length) {
              // Ошибки нет, но ни одна строка не удалилась — почти всегда это RLS-
              // политика DELETE в Supabase, не разрешающая админу удалять чужие строки.
              toast(kk
                ? 'Жойылмады: құқық жетіспейді (Supabase-те questions кестесінің DELETE саясатын әкімшілер үшін тексеріңіз)'
                : 'Не удалилось: не хватает прав (проверьте RLS-политику DELETE для админов в Supabase на таблице questions)');
              return;
            }
            toast(kk?'Сұрақ жойылды':'Вопрос удалён');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
        });
      });
      // Админ: удалить только ответ, оставив сам вопрос (например, если ответ некорректный) — не требует mine.
      wrap.querySelectorAll('[data-qa-admin-del-answer]').forEach(function(btn){
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-qa-admin-del-answer');
          if (!confirm(kk?'Тек жауапты жою керек пе (сұрақ қалады)?':'Удалить только ответ (вопрос останется)?')) return;
          var sb = getSb();
          if (!sb) return;
          try {
            var chk = await sb.auth.getUser();
            if (!(chk && chk.data && chk.data.user)) {
              toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
              if (reloadFn) reloadFn();
              return;
            }
            var res = await sb.from('questions').update({
              answer_text: null, answered_by: null, answered_at: null
            }).eq('id', id).select();
            if (res && res.error) {
              if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
                toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
                if (reloadFn) reloadFn();
              } else {
                toast(res.error.message || (kk?'Қате':'Ошибка'));
              }
              return;
            }
            if (!res || !res.data || !res.data.length) {
              toast(kk
                ? 'Жауап жойылмады: құқық жетіспейді (Supabase-те questions кестесінің UPDATE саясатын әкімшілер үшін тексеріңіз)'
                : 'Ответ не удалился: не хватает прав (проверьте RLS-политику UPDATE для админов в Supabase на таблице questions)');
              return;
            }
            toast(kk?'Жауап жойылды':'Ответ удалён');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
        });
      });
      // Админ: скрыть вопрос от всех, кроме учителей — переиспользует тот же механизм
      // видимости, что и авторская анонимность (is_anonymous=true), плюс отдельный флаг
      // hidden_by_admin — только для значка/различения, что скрыл именно админ.
      wrap.querySelectorAll('[data-qa-admin-hide]').forEach(function(btn){
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-qa-admin-hide');
          if (!confirm(kk?'Бұл сұрақты (әкімші ретінде) барлығынан жасыру керек пе? Тек мұғалімдер көреді.':'Скрыть этот вопрос от всех, кроме учителей (как администратор)?')) return;
          var sb = getSb();
          if (!sb) return;
          try {
            var chk = await sb.auth.getUser();
            if (!(chk && chk.data && chk.data.user)) {
              toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
              if (reloadFn) reloadFn();
              return;
            }
            var res = await sb.from('questions').update({
              is_anonymous: true, hidden_by_admin: true
            }).eq('id', id).select();
            if (res && res.error) {
              if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
                toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
                if (reloadFn) reloadFn();
              } else {
                toast(res.error.message || (kk?'Қате':'Ошибка'));
              }
              return;
            }
            if (!res || !res.data || !res.data.length) {
              toast(kk
                ? 'Жасырылмады: құқық жетіспейді (Supabase-те questions кестесінің UPDATE саясатын, hidden_by_admin бағанын тексеріңіз)'
                : 'Не скрылось: не хватает прав или в Supabase ещё нет колонки hidden_by_admin (проверьте RLS-политику UPDATE и саму колонку в таблице questions)');
              return;
            }
            toast(kk?'Сұрақ жасырылды':'Вопрос скрыт');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
        });
      });
      // Админ: обратное действие — вернуть вопрос в общую видимость.
      wrap.querySelectorAll('[data-qa-admin-unhide]').forEach(function(btn){
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-qa-admin-unhide');
          var sb = getSb();
          if (!sb) return;
          try {
            var chk = await sb.auth.getUser();
            if (!(chk && chk.data && chk.data.user)) {
              toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
              if (reloadFn) reloadFn();
              return;
            }
            var res = await sb.from('questions').update({
              is_anonymous: false, hidden_by_admin: false
            }).eq('id', id).select();
            if (res && res.error) {
              if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
                toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
                if (reloadFn) reloadFn();
              } else {
                toast(res.error.message || (kk?'Қате':'Ошибка'));
              }
              return;
            }
            if (!res || !res.data || !res.data.length) {
              toast(kk
                ? 'Қайтарылмады: құқық жетіспейді'
                : 'Не вернулось: не хватает прав');
              return;
            }
            toast(kk?'Сұрақ барлығына қайта көрінеді':'Вопрос снова виден всем');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
        });
      });
      // ---- build 4.39: раскрыть/свернуть обсуждение ----
      wrap.querySelectorAll('.qa-discuss-toggle').forEach(function(btn) {
        btn.addEventListener('click', function() {
          var id = btn.getAttribute('data-id');
          var body = wrap.querySelector('.qa-discuss-body[data-discuss-for="'+id+'"]');
          if (!body) return;
          var isOpen = body.style.display !== 'none';
          body.style.display = isOpen ? 'none' : 'block';
          if (!isOpen) renderQaDiscussion(id, body, kk);
        });
      });
      // ---- Учитель подтверждает/оспаривает чужой ответ (не свой) ----
      wrap.querySelectorAll('.qa-confirm-btn, .qa-dispute-btn').forEach(function(btn) {
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-id');
          var stance = btn.classList.contains('qa-confirm-btn') ? 'confirm' : 'dispute';
          var sb = getSb(); var sess = authSession();
          if (!sb || !sess) return;
          var text = prompt(kk ? 'Пікір (міндетті емес):' : 'Комментарий (необязательно):', '') || null;
          btn.disabled = true;
          try {
            var ires = await sb.from('qa_comments').insert({ question_id: id, user_id: sess.userId, nick: sess.nick, stance: stance, text: text });
            if (ires && ires.error) { toast((kk?'Қате: ':'Ошибка: ')+(ires.error.message||'')); btn.disabled = false; return; }
            toast(kk?'Жіберілді':'Отправлено');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); btn.disabled = false; }
        });
      });
      // ---- Жалобы на вопрос/ответ форума — тот же submitReport, что и везде ----
      wrap.querySelectorAll('.qa-report-q, .qa-report-a').forEach(function(btn) {
        btn.addEventListener('click', function() {
          var sess = authSession();
          if (!sess) return;
          var fakeMsg = {
            id: btn.getAttribute('data-id'),
            text: btn.getAttribute('data-text') || '',
            nick: btn.getAttribute('data-nick') || '',
            user_id: btn.getAttribute('data-uid') || ''
          };
          submitReport('forum', fakeMsg, null, sess.userId, kk, btn);
        });
      });
      // ---- Админ: заблокировать автора вопроса прямо с форума ----
      // Раньше здесь вызывался blockUserAction — та же функция, что и обычная
      // персональная блокировка собеседника (таблица user_blocks). Это не то
      // действие, которое подписано на кнопке: персональная блокировка лишь
      // отключает ЛС с этим человеком лично для админа и не требует
      // администраторских прав вовсе — а «Заблокировать автора вопроса» на
      // форуме задумана как настоящая, полная блокировка аккаунта нарушителя
      // (как «Заблокировать навсегда» в разделе «Жалобы»), из-за чего и
      // возникало «permission denied»: запрос к user_blocks не давал того
      // эффекта, который ожидался от админской кнопки. Теперь используется
      // тот же проверенный путь через profiles.banned_until, что и у соседних
      // кнопок этой же карточки (бан на форуме, лишение прав учителя) —
      // им уже покрывает RLS-политика UPDATE через is_admin().
      wrap.querySelectorAll('.qa-admin-block').forEach(function(btn) {
        btn.addEventListener('click', async function() {
          var uid = btn.getAttribute('data-uid');
          if (!uid) return;
          var myUidBlock = (typeof _currentAuthedUserId === 'function') ? await _currentAuthedUserId() : null;
          if (uid && myUidBlock && uid === myUidBlock) { toast(kk ? 'Өзіңізді бұғаттауға болмайды' : 'Нельзя заблокировать самого себя'); return; }
          if (!confirm(kk?'Пайдаланушыны мәңгі бұғаттауға сенімдісіз бе?':'Заблокировать этого пользователя навсегда?')) return;
          btn.disabled = true;
          var sb2 = getSb();
          try {
            var upd = await sb2.from('profiles').update({
              banned_until: '9999-01-01T00:00:00.000Z',
              banned_reason: (kk?'Форум арқылы бұғатталды':'Заблокирован через форум')
            }).eq('id', uid).select();
            if (upd && upd.error) {
              toast((kk?'Қате: ':'Ошибка: ')+(upd.error.message||''));
              btn.disabled = false;
              return;
            }
            if (!upd || !upd.data || !upd.data.length) {
              toast(kk
                ? 'Бұғатталмады: құқық жетіспейді (profiles кестесінің UPDATE саясатын тексеріңіз)'
                : 'Не заблокировался: не хватает прав (проверьте RLS-политику UPDATE для profiles)');
              btn.disabled = false;
              return;
            }
            try { await sb2.from('ban_history').insert({ user_id: uid, type: 'permanent', reason: (kk?'Форум арқылы бұғатталды':'Заблокирован через форум'), until: '9999-01-01T00:00:00.000Z', banned_by: myUidBlock }); } catch(e) {}
            toast(kk?'Бұғатталды':'Заблокирован');
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
          btn.disabled = false;
        });
      });
      // ---- Админ: временно забанить автора от отправки новых вопросов ----
      wrap.querySelectorAll('.qa-admin-banask').forEach(function(btn) {
        btn.addEventListener('click', async function() {
          var uid = btn.getAttribute('data-uid');
          var qid = btn.getAttribute('data-id');
          var myUidQa = (typeof _currentAuthedUserId === 'function') ? await _currentAuthedUserId() : null;
          if (uid && myUidQa && uid === myUidQa) { toast(kk ? 'Өзіңізді бандауға болмайды' : 'Нельзя забанить самого себя'); return; }
          var sel = wrap.querySelector('.qa-ban-duration[data-forid="'+qid+'"]');
          var dur = sel ? sel.value : '1d';
          var amount = parseInt(dur, 10);
          var ms = dur.slice(-1) === 'h' ? amount * 3600000 : amount * 86400000;
          var until = new Date(Date.now() + ms).toISOString();
          if (!confirm(kk?'Пайдаланушыны форумда сұрақ жіберуден таңдалған мерзімге бандауға сенімдісіз бе?':'Забанить пользователя от отправки вопросов на форуме на выбранный срок?')) return;
          btn.disabled = true;
          var sb = getSb();
          try {
            var upd = await sb.from('profiles').update({ forum_ask_banned_until: until }).eq('id', uid);
            if (upd && upd.error) { toast((kk?'Қате: ':'Ошибка: ')+(upd.error.message||'')); btn.disabled = false; return; }
            toast(kk?'Бандалды':'Забанен от вопросов на форуме');
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); btn.disabled = false; }
        });
      });
      // ---- Админ: навсегда лишить учителя права отвечать (принудительно и
      // необратимо переводит в ученики — сам себе такое не отменит). ----
      wrap.querySelectorAll('.qa-admin-demote').forEach(function(btn) {
        btn.addEventListener('click', async function() {
          var uid = btn.getAttribute('data-uid');
          if (!uid) return;
          var myUidDemote = (typeof _currentAuthedUserId === 'function') ? await _currentAuthedUserId() : null;
          if (myUidDemote && uid === myUidDemote) { toast(kk ? 'Өзіңізді мұғалім құқығынан айыра алмайсыз' : 'Нельзя лишить самого себя права быть учителем'); return; }
          if (!confirm(kk
            ? 'МАҢЫЗДЫ: бұл мұғалімді мәңгі оқушыға ауыстырады, ол бұдан былай ешқашан қайта мұғалім бола алмайды. Жалғастыру керек пе?'
            : 'ВАЖНО: это навсегда переведёт учителя в ученики, он больше никогда не сможет снова выбрать «Учитель». Продолжить?')) return;
          btn.disabled = true;
          var sb = getSb();
          try {
            var upd = await sb.from('profiles').update({ level: 'student', teacher_locked: true }).eq('id', uid);
            if (upd && upd.error) { toast((kk?'Қате: ':'Ошибка: ')+(upd.error.message||'')); btn.disabled = false; return; }
            toast(kk?'Оқушыға ауыстырылды, қайтару мүмкін емес':'Переведён в ученики без возможности вернуться');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); btn.disabled = false; }
        });
      });
      // ---- Админ: снять пометку «требует проверки» (build 4.46) — после
      // того как посмотрел на оспоренный ответ и принял решение (оставить,
      // удалить ответ, и т.п.), убирает предупреждающий значок с карточки. ----
      wrap.querySelectorAll('.qa-admin-clearflag').forEach(function(btn) {
        btn.addEventListener('click', async function() {
          var id = btn.getAttribute('data-id');
          btn.disabled = true;
          var sb = getSb();
          try {
            var upd = await sb.from('questions').update({ dispute_flagged: false }).eq('id', id);
            if (upd && upd.error) { toast((kk?'Қате: ':'Ошибка: ')+(upd.error.message||'')); btn.disabled = false; return; }
            toast(kk?'Белгі алынды':'Пометка снята');
            if (reloadFn) reloadFn();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); btn.disabled = false; }
        });
      });
    }
    // ========== КАТЕГОРИИ ВОПРОСОВ ФОРУМА (build 4.52) ==========
    // Общий список — используется и в форме вопроса, и как фильтр в Форуме.
    var QA_CATEGORIES = [
      ['fiqh', 'Фикх', 'Фиқһ'],
      ['aqidah', 'Акида', 'Ақида'],
      ['salah', 'Намаз', 'Намаз'],
      ['fasting', 'Пост/Рамадан', 'Ораза/Рамазан'],
      ['zakat', 'Закят', 'Зекет'],
      ['hajj', 'Хадж/Умра', 'Қажылық/Умра'],
      ['family', 'Семья/брак', 'Отбасы/неке'],
      ['quran', 'Коран/чтение', 'Құран/оқу'],
      ['hadith', 'Хадисы', 'Хадистер'],
      ['other', 'Другое', 'Басқа']
    ];
    function qaCategoryLabel(id, kk) {
      var c = QA_CATEGORIES.find(function(x){ return x[0] === id; });
      return c ? (kk ? c[2] : c[1]) : null;
    }
    async function renderMyQA() {
      var el = document.getElementById('myqa-body');
      if (!el) return;
      var kk = state.settings && state.settings.lang === 'kk';
      var sb = getSb();
      if (!sb) {
        el.innerHTML = '<div class="empty-state"><p>'+(kk?'Бөлім тек онлайн-режимде қолжетімді.':'Раздел доступен только в онлайн-режиме.')+'</p></div>';
        return;
      }
      var sess = authSession();
      if (!sess || !sess.online) {
        el.innerHTML =
          '<div class="card"><p>'+(kk?'Сұрақ қою және жауаптарды көру үшін аккаунтқа кіріңіз.':'Чтобы задать вопрос и видеть ответы, войдите в аккаунт.')+'</p>' +
          '<button type="button" class="btn btn-primary" id="myqa-go-login" style="width:100%;margin-top:0.5rem">'+(kk?'Кіру/Тіркелу':'Войти / Зарегистрироваться')+'</button></div>';
        document.getElementById('myqa-go-login')?.addEventListener('click', function(){ showView('login'); });
        return;
      }
      // Локальный флаг «online» мог устареть (токен истёк/недействителен) —
      // проверяем реальную сессию у Supabase, иначе запрос уйдёт как anon
      // и упадёт с "permission denied", хотя у authenticated права есть.
      el.innerHTML = skeletonHtml(3);
      var authedUser = null;
      try {
        var ures = await sb.auth.getUser();
        authedUser = ures && ures.data && ures.data.user;
      } catch(e) { authedUser = null; }
      if (!authedUser) {
        authSetSession(null);
        el.innerHTML =
          '<div class="card"><p>'+(kk?'Сессия аяқталды немесе жарамсыз. Қайта кіріңіз.':'Сессия истекла или недействительна. Войдите заново.')+'</p>' +
          '<button type="button" class="btn btn-primary" id="myqa-go-login" style="width:100%;margin-top:0.5rem">'+(kk?'Кіру':'Войти')+'</button></div>';
        document.getElementById('myqa-go-login')?.addEventListener('click', function(){ showView('login'); });
        return;
      }
      if (sess.userId !== authedUser.id) { sess.userId = authedUser.id; authSetSession(sess); }
      // «Мои вопросы/ответы» — приватный раздел: здесь показываются только вопросы,
      // заданные самим пользователем. Ни учителя, ни админы, ни другие пользователи
      // чужие вопросы отсюда не видят и отвечать отсюда не могут (для ответа учителя
      // используют «Форум» — см. renderForum). Поэтому кнопки «Ответить» тут нет вовсе.
      el.innerHTML =
        tipCard(kk
          ? 'Мұнда тек сіздің өз сұрақтарыңыз көрінеді — оларды басқа ешкім (мұғалімдер мен әкімшілерді қоса) көрмейді. Анонимды емес сұрақ сонымен қатар «Форумда» да көрінеді (жауап алғанға дейін де).<br><br>Не істей аласыз:<br>• Жаңа сұрақ жіберу (аноним не жоқ).<br>• Мұғалім жауап бергенде осы жерде көресіз.'
          : 'Здесь видны только ваши собственные вопросы — их не видит никто другой, включая учителей и админов. Неанонимный вопрос также виден в «Форуме» (даже пока ещё без ответа).<br><br>Что можно сделать:<br>• Отправить новый вопрос (анонимно или нет).<br>• Здесь же появится ответ учителя, когда он его напишет.') +
        '<div class="card">' +
          '<b>'+(kk?'Сұрақ қою':'Задать вопрос')+'</b>' +
          '<label style="display:block;margin-top:0.5rem;font-size:0.85rem">'+(kk?'Сұрағыңыз':'Ваш вопрос')+'</label>' +
          '<textarea id="qa-text" rows="3" style="'+authFormStyle()+'resize:vertical" placeholder="'+(kk?'Сұрағыңызды осында жазыңыз...':'Напишите ваш вопрос здесь...')+'"></textarea>' +
          '<label style="display:block;font-size:0.85rem">'+(kk?'Өзіңіз туралы (міндетті емес, түсінікті болу үшін)':'О себе (необязательно, для ясности ситуации)')+'</label>' +
          '<div style="display:flex;gap:0.4rem;flex-wrap:wrap">' +
            '<input id="qa-age" type="number" min="1" max="120" placeholder="'+(kk?'Жасы':'Возраст')+'" style="flex:1;min-width:80px;'+authFormStyle()+'">' +
            '<select id="qa-gender" style="flex:1;min-width:110px;'+authFormStyle()+'">' +
              '<option value="">'+(kk?'Жынысы':'Пол')+'</option>' +
              '<option value="male">'+(kk?'Ер':'Мужской')+'</option>' +
              '<option value="female">'+(kk?'Әйел':'Женский')+'</option>' +
            '</select>' +
          '</div>' +
          '<input id="qa-country" type="text" placeholder="'+(kk?'Ел':'Страна')+'" style="'+authFormStyle()+'">' +
          '<select id="qa-mazhab" style="'+authFormStyle()+'">' +
            '<option value="">'+(kk?'Мазһаб':'Мазхаб')+'</option>' +
            '<option value="hanafi">Ханафи</option>' +
            '<option value="shafii">'+(kk?'Шафиғи':'Шафии')+'</option>' +
            '<option value="maliki">Малики</option>' +
            '<option value="hanbali">Ханбали</option>' +
            '<option value="other">'+(kk?'Басқа/жоқ':'Другой/нет')+'</option>' +
          '</select>' +
          '<textarea id="qa-extra" rows="2" style="'+authFormStyle()+'resize:vertical" placeholder="'+(kk?'Қосымша мән-жайлар (қаласаңыз)':'Дополнительные детали ситуации (по желанию)')+'"></textarea>' +
          '<select id="qa-category" style="'+authFormStyle()+'">' +
            '<option value="">'+(kk?'Тақырып (қаласаңыз)':'Тема вопроса (по желанию)')+'</option>' +
            QA_CATEGORIES.map(function(c){ return '<option value="'+c[0]+'">'+(kk?c[2]:c[1])+'</option>'; }).join('') +
          '</select>' +
          '<label style="display:flex;align-items:center;gap:0.4rem;font-size:0.85rem;margin:0.3rem 0 0.6rem"><input type="checkbox" id="qa-anon"> '+(kk?'Анонимды сұрақ (тек мұғалімдерге көрінеді, басқаларға көрінбейді)':'Анонимный вопрос (виден только учителям, остальным не виден)')+'</label>' +
          '<div id="qa-draft-hint" style="display:none;font-size:0.78rem;color:var(--text-muted);margin-bottom:0.4rem"></div>' +
          '<button type="button" class="btn btn-sm" id="qa-save" style="width:100%">💾 '+(kk?'Сақтау (жібермей)':'Сохранить (не отправляя)')+'</button>' +
          '<button type="button" class="btn btn-primary" id="qa-submit" style="width:100%;margin-top:0.4rem">'+(kk?'Жіберу':'Отправить')+'</button>' +
        '</div>' +
        '<div id="qa-list-wrap">'+skeletonHtml(3)+'</div>';

      // ---- Черновик вопроса: сохраняется в localStorage, сервера не трогает.
      // Нужно в первую очередь на случай бана: отправка (INSERT в questions)
      // упадёт из-за бана, а «Сохранить» позволяет всё равно не потерять
      // написанное — сохранить сейчас и отправить позже, когда бан снимут,
      // либо просто сохранить и спокойно перечитать вопрос перед отправкой. ----
      var QA_DRAFT_KEY = 'quran_qa_draft';
      function qaDraftFields() {
        return {
          text: document.getElementById('qa-text'),
          age: document.getElementById('qa-age'),
          gender: document.getElementById('qa-gender'),
          country: document.getElementById('qa-country'),
          mazhab: document.getElementById('qa-mazhab'),
          extra: document.getElementById('qa-extra'),
          category: document.getElementById('qa-category'),
          anon: document.getElementById('qa-anon')
        };
      }
      function qaLoadDraft() {
        var raw = null;
        try { raw = localStorage.getItem(QA_DRAFT_KEY); } catch(e) {}
        if (!raw) return;
        var d = null;
        try { d = JSON.parse(raw); } catch(e) { return; }
        if (!d) return;
        var f = qaDraftFields();
        if (f.text) f.text.value = d.text || '';
        if (f.age) f.age.value = d.age || '';
        if (f.gender) f.gender.value = d.gender || '';
        if (f.country) f.country.value = d.country || '';
        if (f.mazhab) f.mazhab.value = d.mazhab || '';
        if (f.extra) f.extra.value = d.extra || '';
        if (f.category) f.category.value = d.category || '';
        if (f.anon) f.anon.checked = !!d.anon;
        var hint = document.getElementById('qa-draft-hint');
        if (hint && d.savedAt) {
          var dt = new Date(d.savedAt);
          hint.style.display = 'block';
          hint.textContent = (kk ? 'Сақталған нобай жүктелді (' : 'Загружен сохранённый черновик (') + dt.toLocaleString() + ')';
        }
      }
      function qaClearDraft() {
        try { localStorage.removeItem(QA_DRAFT_KEY); } catch(e) {}
        var hint = document.getElementById('qa-draft-hint');
        if (hint) { hint.style.display = 'none'; hint.textContent = ''; }
      }
      qaLoadDraft();

      document.getElementById('qa-save')?.addEventListener('click', function() {
        var f = qaDraftFields();
        var text = (f.text && f.text.value || '').trim();
        if (!text) { toast(kk?'Сұрақты жазыңыз':'Напишите вопрос'); return; }
        var d = {
          text: text,
          age: (f.age && f.age.value || '').trim(),
          gender: (f.gender && f.gender.value) || '',
          country: (f.country && f.country.value || '').trim(),
          mazhab: (f.mazhab && f.mazhab.value) || '',
          extra: (f.extra && f.extra.value || '').trim(),
          category: (f.category && f.category.value) || '',
          anon: !!(f.anon && f.anon.checked),
          savedAt: new Date().toISOString()
        };
        try { localStorage.setItem(QA_DRAFT_KEY, JSON.stringify(d)); } catch(e) {}
        var hint = document.getElementById('qa-draft-hint');
        if (hint) { hint.style.display = 'block'; hint.textContent = kk ? 'Нобай сақталды — қашан ыңғайлы болса, сонда «Жіберу» басыңыз.' : 'Черновик сохранён — отправьте, когда будет удобно.'; }
        toast(kk?'Сақталды':'Сохранено');
      });

      document.getElementById('qa-submit')?.addEventListener('click', async function() {
        var textEl = document.getElementById('qa-text');
        var text = (textEl.value || '').trim();
        if (!text) { toast(kk?'Сұрақты жазыңыз':'Напишите вопрос'); return; }
        var age = (document.getElementById('qa-age').value || '').trim();
        var gender = document.getElementById('qa-gender').value || '';
        var country = (document.getElementById('qa-country').value || '').trim();
        var mazhab = document.getElementById('qa-mazhab').value || '';
        var extra = (document.getElementById('qa-extra').value || '').trim();
        var category = document.getElementById('qa-category').value || null;
        var anon = !!document.getElementById('qa-anon').checked;
        var btn = this;
        btn.disabled = true;
        try {
          // На случай, если токен истёк за время заполнения формы — свежая проверка
          var chk = await sb.auth.getUser();
          if (!(chk && chk.data && chk.data.user)) {
            toast(kk?'Сессия аяқталды, қайта кіріңіз':'Сессия истекла, войдите заново');
            btn.disabled = false;
            renderMyQA();
            return;
          }
          var res = await sb.from('questions').insert({
            user_id: sess.userId,
            nick: sess.nick,
            question_text: text,
            age: age ? parseInt(age,10) : null,
            gender: gender || null,
            country: country || null,
            mazhab: mazhab || null,
            extra_text: extra || null,
            category: category,
            is_anonymous: anon
          });
          if (res && res.error) {
            if (res.error.code === '42501' || /permission denied/i.test(res.error.message||'')) {
              toast(kk?'Сессия жарамсыз, қайта кіріңіз':'Сессия недействительна, войдите заново');
              renderMyQA();
            } else {
              toast(res.error.message || (kk?'Қате':'Ошибка'));
            }
            btn.disabled = false;
            return;
          }
          toast(kk?'Сұрақ жіберілді':'Вопрос отправлен');
          textEl.value = '';
          document.getElementById('qa-age').value = '';
          document.getElementById('qa-country').value = '';
          document.getElementById('qa-extra').value = '';
          document.getElementById('qa-anon').checked = false;
          qaClearDraft();
          loadQaList();
        } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); }
        btn.disabled = false;
      });

      function loadQaList() {
        var wrap = document.getElementById('qa-list-wrap');
        if (!wrap) return;
        wrap.innerHTML = skeletonHtml(3);
        // Фильтр по user_id — показываем только вопросы самого пользователя. Это
        // ограничение задано на клиенте явно, а не полагается только на RLS,
        // но для настоящей защиты данных RLS на таблице questions всё равно нужен —
        // клиентский фильтр можно обойти, обратившись к Supabase напрямую.
        sb.from('questions').select('*').eq('user_id', sess.userId).order('created_at', { ascending: false }).limit(100).then(function(res) {
          if (res && res.error) { wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Қате: ':'Ошибка: ')+(res.error.message||'')+'</p></div>'; return; }
          var rows = (res && res.data) || [];
          if (!rows.length) { wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Әзірге сұрақтарыңыз жоқ.':'У вас пока нет вопросов.')+'</p></div>'; return; }
          // allowAnswer: false — в «Мои вопросы/ответы» кнопки «Ответить» нет ни у кого,
          // это приватная лента только для просмотра своих вопросов и удаления неотвеченных.
          // isAdmin: администраторские кнопки удаления доступны и здесь (это ведь и его
          // собственные вопросы), хотя обычно это тот же результат, что и обычная «Удалить».
          var qaIsAdmin = (typeof isAdminUser === 'function') && isAdminUser();
          wrap.innerHTML = rows.map(function(q){ return renderQaCard(q, sess, kk, { allowAnswer: false, allowDelete: true, isAdmin: qaIsAdmin }); }).join('');
          bindQaAnswerButtons(wrap, kk, renderMyQA);

          // Раздел открыт — все текущие ответы на мои вопросы считаем показанными.
          try {
            var _qaAnswered = rows.filter(function(r){ return r.answer_text; }).map(function(r){ return r.id; });
            _obSeenAdd('quran_seen_qa_answers', _qaAnswered);
          } catch(e) {}
          _obMarkSeenNow('myqa');
        }).catch(function(e) {
          wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Қате: ':'Ошибка: ')+(e.message||e)+'</p></div>';
        });
      }
      loadQaList();
    }
    // ===== Форум: неанонимные вопросы/ответы видят все; анонимные — только учителя =====
    async function renderForum() {
      var el = document.getElementById('forum-body');
      if (!el) return;
      var kk = state.settings && state.settings.lang === 'kk';
      var sb = getSb();
      if (!sb) {
        el.innerHTML = '<div class="empty-state"><p>'+(kk?'Бөлім тек онлайн-режимде қолжетімді.':'Раздел доступен только в онлайн-режиме.')+'</p></div>';
        return;
      }
      var sess = authSession();
      if (!sess || !sess.online) {
        el.innerHTML =
          '<div class="card"><p>'+(kk?'Форумды көру үшін аккаунтқа кіріңіз.':'Чтобы посмотреть форум, войдите в аккаунт.')+'</p>' +
          '<button type="button" class="btn btn-primary" id="forum-go-login" style="width:100%;margin-top:0.5rem">'+(kk?'Кіру/Тіркелу':'Войти / Зарегистрироваться')+'</button></div>';
        document.getElementById('forum-go-login')?.addEventListener('click', function(){ showView('login'); });
        return;
      }
      el.innerHTML = skeletonHtml(3);
      var authedUser = null;
      try {
        var ures = await sb.auth.getUser();
        authedUser = ures && ures.data && ures.data.user;
      } catch(e) { authedUser = null; }
      if (!authedUser) {
        authSetSession(null);
        el.innerHTML =
          '<div class="card"><p>'+(kk?'Сессия аяқталды немесе жарамсыз. Қайта кіріңіз.':'Сессия истекла или недействительна. Войдите заново.')+'</p>' +
          '<button type="button" class="btn btn-primary" id="forum-go-login" style="width:100%;margin-top:0.5rem">'+(kk?'Кіру':'Войти')+'</button></div>';
        document.getElementById('forum-go-login')?.addEventListener('click', function(){ showView('login'); });
        return;
      }
      if (sess.userId !== authedUser.id) { sess.userId = authedUser.id; authSetSession(sess); }
      // Уровень (учитель/ученик) берём свежим из profiles, а не из sess.level:
      // sess — это кэш в localStorage, который мог остаться от предыдущего входа
      // (например, если уровень поменяли на другом устройстве, или админ
      // принудительно перевёл учителя в ученики через «Навсегда лишить права
      // быть учителем»). Если полагаться только на кэш, ученик, который раньше
      // был учителем в этой же вкладке, продолжит видеть анонимные/скрытые
      // вопросы, пока не перезайдёт в аккаунт вручную.
      var isTeacher = sess.level === 'teacher';
      try {
        var lvlRes = await sb.from('profiles').select('level').eq('id', authedUser.id).maybeSingle();
        if (lvlRes && !lvlRes.error && lvlRes.data) {
          var freshLevel = lvlRes.data.level || 'student';
          isTeacher = freshLevel === 'teacher';
          if (sess.level !== freshLevel) { sess.level = freshLevel; authSetSession(sess); }
        }
      } catch(e) { /* сеть недоступна — остаёмся на кэше sess.level */ }
      el.innerHTML =
        tipCard(kk
          ? (isTeacher
            ? 'Форум — сұрақ-жауап тізімі. Сіз мұғаліміз, сондықтан анонимды сұрақтар да көрінеді және оларға жауап бере аласыз.<br><br>Не істей аласыз:<br>• Жауап жазу — жаңа жауап алдымен «тексерілмеген» болып тұрады.<br>• Басқа мұғалімнің жауабына бір рет «Растаймын»/«Келіспеймін» деу (өз жауабыңызды растай алмайсыз, дауыс бергеннен кейін қайта дауыс беру мүмкін емес). Келіспеушілер болмаса — 2 растау жеткілікті. Кем дегенде 1 келіспеу пайда болса, статус «тексерілмегенге» түседі және растағандар келіспегендерден 5-ке артық болғанда ғана «тексерілді» болады (мыс. 6 растау мен 1 келіспеу — тексерілді, ал 4 растау мен 1 келіспеу — жоқ).<br>• 2 бөлек мұғалім келіспесе — сұрақ пен жауап шағымсыз-ақ әкімшінің назарына автоматты түседі.<br>• Пікір қалдыру, сұрақ-жауапқа шағымдану.'
            : 'Форум — басқалардың мұғалімдерге қойған сұрақтары мен жауаптары. Анонимды сұрақтар тек мұғалімдерге көрінеді.<br><br>Не істей аласыз:<br>• Сұрақ-жауапты ашып оқу, пікірлерін көру.<br>• Жауапқа түсіндірме/сұрақ жазу (сіз сұраған болсаңыз да).<br>• Сұрақ-жауапқа шағымдану.')
          : (isTeacher
            ? 'Форум — список вопросов и ответов. Вы учитель, поэтому вам видны и анонимные вопросы — на них тоже можно отвечать.<br><br>Что можно сделать:<br>• Написать ответ — новый ответ сначала стоит как «не проверено».<br>• Один раз поставить «Согласен»/«Не согласен» на чужой ответ (свой подтвердить нельзя, после голоса переголосовать уже не получится). Если несогласных нет — хватает 2 согласных. Как только появляется хотя бы 1 «Не согласен», статус падает обратно в «не проверено», и «проверено» вернётся только когда согласных станет больше несогласных на 5 и более (например 6 согласных и 1 несогласный — проверено, а 4 согласных и 1 несогласный — ещё нет).<br>• Если не согласны 2 разных учителя — вопрос с ответом сам попадает на заметку админу, без жалобы.<br>• Оставить комментарий, пожаловаться на вопрос или ответ.'
            : 'Форум — вопросы, которые другие задавали учителям, и ответы на них. Анонимные вопросы видны только учителям.<br><br>Что можно сделать:<br>• Открыть и прочитать вопрос-ответ, посмотреть комментарии.<br>• Написать уточнение к ответу (даже если вопрос не ваш).<br>• Задать свой вопрос из раздела «Черновик вопроса», пожаловаться на вопрос или ответ.')) +
        '<div id="forum-list-wrap">'+skeletonHtml(3)+'</div>';

      // build 4.52: поиск и категории — фильтруем то, что уже загружено
      // (до 200 вопросов зараз), без лишних обращений к базе на каждый
      // символ ввода.
      var _forumAllRows = [];
      var _forumSearchQ = '';
      var _forumCategory = 'all';

      function renderForumFilterBar() {
        var bar = document.createElement('div');
        bar.id = 'forum-filter-bar';
        bar.style.cssText = 'margin-bottom:0.6rem';
        bar.innerHTML =
          '<input type="text" id="forum-search-input" placeholder="'+(kk?'Сұрақтар мен жауаптардан іздеу...':'Искать по вопросам и ответам...')+'" style="width:100%;box-sizing:border-box;padding:0.45rem 0.6rem;border-radius:0.5rem;border:1px solid var(--border);background:var(--bg);color:var(--text);margin-bottom:0.45rem">' +
          '<select id="forum-category-select" style="width:100%;box-sizing:border-box;padding:0.4rem 0.6rem;border-radius:0.5rem;border:1px solid var(--border);background:var(--bg);color:var(--text)">' +
            '<option value="all">'+(kk?'Барлық тақырыптар':'Все темы')+'</option>' +
            QA_CATEGORIES.map(function(c){ return '<option value="'+c[0]+'">'+(kk?c[2]:c[1])+'</option>'; }).join('') +
          '</select>';
        var wrapEl = document.getElementById('forum-list-wrap');
        wrapEl.parentNode.insertBefore(bar, wrapEl);
        document.getElementById('forum-search-input').addEventListener('input', function(ev) {
          _forumSearchQ = (ev.target.value || '').trim().toLowerCase();
          renderForumFilteredList();
        });
        document.getElementById('forum-category-select').addEventListener('change', function(ev) {
          _forumCategory = ev.target.value || 'all';
          renderForumFilteredList();
        });
      }

      function renderForumFilteredList() {
        var wrap = document.getElementById('forum-list-wrap');
        if (!wrap) return;
        var filtered = _forumAllRows.filter(function(q) {
          if (_forumCategory !== 'all' && q.category !== _forumCategory) return false;
          if (_forumSearchQ) {
            var hay = ((q.question_text||'') + ' ' + (q.answer_text||'') + ' ' + (q.extra_text||'')).toLowerCase();
            if (hay.indexOf(_forumSearchQ) < 0) return false;
          }
          return true;
        });
        if (!filtered.length) {
          wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Ештеңе табылмады.':'Ничего не найдено.')+'</p></div>';
          return;
        }
        var forumIsAdmin = (typeof isAdminUser === 'function') && isAdminUser();
        wrap.innerHTML = filtered.map(function(q){ return renderQaCard(q, sess, kk, { allowAnswer: isTeacher, allowDelete: true, isAdmin: forumIsAdmin, myVotedIds: window._forumVotedIds || new Set() }); }).join('');
        bindQaAnswerButtons(wrap, kk, renderForum);
      }

      function loadForumList() {
        var wrap = document.getElementById('forum-list-wrap');
        if (!wrap) return;
        wrap.innerHTML = skeletonHtml(3);
        // Не-учителя запрашивают только is_anonymous = false и hidden_by_admin = false —
        // это клиентский фильтр, повторяющий требуемое правило видимости (то же самое,
        // что стоит в RLS-политике "select questions visibility"); окончательную гарантию
        // защиты даёт только сама RLS-политика SELECT на таблице questions в Supabase.
        // Раньше здесь фильтровался только is_anonymous — hidden_by_admin (вопрос,
        // скрытый админом как слишком лёгкий/неважный) на клиенте не проверялся вовсе,
        // из-за чего при любой прорехе в RLS (например старая политика не была
        // удалена) скрытый вопрос всё равно показывался ученику.
        var query = sb.from('questions').select('*').order('created_at', { ascending: false }).limit(200);
        if (!isTeacher) query = query.eq('is_anonymous', false).eq('hidden_by_admin', false);
        query.then(async function(res) {
          if (res && res.error) { wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Қате: ':'Ошибка: ')+(res.error.message||'')+'</p></div>'; return; }
          var rows = (res && res.data) || [];
          // Подстраховка на клиенте: даже если сервер вдруг вернёт лишнее, не-учитель
          // анонимные и скрытые админом вопросы всё равно не увидит.
          if (!isTeacher) rows = rows.filter(function(q){ return !q.is_anonymous && !q.hidden_by_admin; });
          if (!rows.length) { wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Әзірге сұрақтар жоқ.':'Пока нет вопросов.')+'</p></div>'; return; }
          // build 4.46: для учителя отдельно узнаём, по каким из показанных
          // вопросов он уже поставил «Согласен»/«Не согласен» — чтобы скрыть
          // кнопки повторного голосования (см. renderQaCard/alreadyVoted).
          var myVotedIds = new Set();
          if (isTeacher) {
            try {
              var answeredIds = rows.filter(function(q){ return q.answer_text; }).map(function(q){ return q.id; });
              if (answeredIds.length) {
                var voteRes = await sb.from('qa_comments').select('question_id').eq('user_id', sess.userId).not('stance', 'is', null).in('question_id', answeredIds);
                ((voteRes && voteRes.data) || []).forEach(function(v){ myVotedIds.add(v.question_id); });
              }
            } catch(e) {}
          }
          window._forumVotedIds = myVotedIds;
          _forumAllRows = rows;
          if (!document.getElementById('forum-filter-bar')) renderForumFilterBar();
          renderForumFilteredList();
        }).catch(function(e) {
          wrap.innerHTML = '<div class="empty-state"><p>'+(kk?'Қате: ':'Ошибка: ')+(e.message||e)+'</p></div>';
        });
      }
      loadForumList();
    }
    // ========== ОБЩИЙ ЧАТ (публичный, все читают и пишут) ==========
    // Таблица chat_messages создаётся отдельным SQL-скриптом (см. ниже в чате с пользователем).
    // Здесь: загрузка истории, отправка сообщений и Realtime-подписка (новые сообщения
    // появляются у всех участников без перезагрузки страницы).
    // build 6.53: общий чат временно закрыт («в разработке»): ни показа, ни запросов к базе.
    // Вернуть — поставить false (правила чатов и согласие уже подключены).
    var PUBLIC_CHAT_DISABLED = true;
    var _publicChatChannel = null;   // текущая Realtime-подписка (канал Supabase)
    var _publicChatBound = false;    // чтобы не вешать обработчик beforeunload повторно
    // Отписка от Realtime-канала. Вызывается при уходе с раздела «Общий чат»
    // (см. showView) — иначе при частом переключении вкладок будут копиться
    // открытые сокет-соединения.
    function unsubscribePublicChat() {
      if (_publicChatChannel) {
        try {
          var sb = getSb();
          if (sb) sb.removeChannel(_publicChatChannel);
        } catch(e) { console.warn('unsubscribePublicChat', e); }
        _publicChatChannel = null;
      }
    }
    // ===== Долгий тап = меню действий (build 4.62) — раньше у каждого
    // сообщения всегда был виден ряд мелких иконок (↩️➡️🙂+✏️🚩🗑), тесно на
    // телефоне. Теперь они спрятаны внутри '.msg-actions-row' (display:none
    // по умолчанию) и появляются по долгому тапу/удержанию (или правому
    // клику на десктопе) — как в Telegram/WhatsApp. Сами кнопки и их классы
    // (.pchat-reply, .grp-fwd, .dm-edit и т.д.) не изменились, поэтому уже
    // существующие делегированные обработчики клика продолжают работать без
    // переделки — просто раньше скрытая строка теперь показывается.
    var _msgActionsSuppressClick = false;
    var _msgActionsSuppressClickSafety = null;
    var SWIPE_REPLY_TRIGGER = 64;   // px — с этого расстояния свайп точно сработает как «ответить»
    var SWIPE_REPLY_MAX = 80;       // px — дальше карточка не тянется
    function _closeAllMsgActionRows() {
      document.querySelectorAll('.msg-actions-row[data-open="1"]').forEach(function(row) {
        row.style.display = 'none';
        row.removeAttribute('data-open');
        var c = row.closest('.chat-msg-card');
        if (c) c.classList.remove('msg-selected');
      });
    }
    if (!window._msgActionsDocBound) {
      window._msgActionsDocBound = true;
      // Единственный глобальный обработчик закрытия — не по одному на чат
      // (иначе при каждом повторном открытии раздела копился бы новый
      // слушатель на document, который никогда не снимается).
      document.addEventListener('click', function(ev) {
        if (_msgActionsSuppressClick) { _msgActionsSuppressClick = false; return; }
        if (ev.target.closest('.msg-actions-row')) return; // сама кнопка действия — её обработчик разберётся (и обычно перерисует карточку)
        _closeAllMsgActionRows();
      });
    }
    // cardSelector — например '[data-mid]' или '[data-msg-id]', в зависимости
    // от чата. Вызывается один раз на каждый рендер списка сообщений.
    //
    // build 4.77: раньше это были ДВЕ независимые функции — _bindLongPressReveal
    // (долгое удержание → меню действий) и _bindSwipeReply (свайп влево →
    // ответить) — обе вешали свои pointerdown/pointermove/pointerup на один
    // и тот же listEl и независимо решали, что делать с одним и тем же
    // жестом. На практике палец никогда не стоит абсолютно неподвижно:
    // при обычном удержании случайное дрожание в пару пикселей могло
    // раньше срабатывания таймера меню (450мс) превысить порог свайпа
    // (было 8px) и «захватить» указатель через setPointerCapture — после
    // этого удержание фактически превращалось в едва заметный свайп, меню
    // действий не открывалось, и пользователь попадал на нативное
    // выделение текста (и тот самый конфликт со словарём), потому что
    // ничего из двух независимых обработчиков вовремя не остановило жест.
    // Стабильно меню открывалось только там, где кнопки свайпа физически
    // нет (см. findReplyBtn) — отсюда и «работает только у отметки
    // прочитано». Теперь это ОДИН обработчик с единым состоянием: держим
    // неподвижно → меню; тянем влево дальше мёртвой зоны → свайп-ответ;
    // тянем вертикально/вправо → ничего не перехватываем, обычная
    // прокрутка списка. Гонки между двумя независимыми машинами состояний
    // больше нет в принципе.
    function _bindMsgCardGestures(listEl, cardSelector) {
      // build 4.94: DEAD_ZONE был всего 10px — этого мало для «просто
      // держу неподвижно»: обычное дрожание пальца на телефоне легко
      // превышает 10px за 450мс удержания. Стоило пальцу чуть дрогнуть —
      // жест тут же считался свайпом (или просто отменялся, если дрожание
      // было не строго влево), и меню действий не открывалось вовсе —
      // вместо него мог случайно сработать ответ на сообщение. Увеличено
      // до 20px — жест всё ещё требует явного намерения свайпнуть (порог
      // срабатывания SWIPE_REPLY_TRIGGER = 64px намного больше и не
      // меняется), но случайное дрожание при удержании больше не мешает.
      var REVEAL_DURATION = 450, DEAD_ZONE = 20;
      var timer = null, startX = 0, startY = 0, card = null, pid = null;
      var axisLocked = false, swiping = false, revealed = false;
      function findReplyBtn(c) { return c && c.querySelector('.pchat-reply, .dm-reply, .grp-reply'); }
      function clearTimer() { clearTimeout(timer); timer = null; }
      function resetSwipeVisual(c, animate) {
        if (!c) return;
        if (animate === false) c.removeAttribute('data-swiping'); else c.setAttribute('data-swiping', '0');
        c.style.transform = '';
        var icon = c.querySelector('.chat-msg-swipe-reply-icon');
        if (icon) icon.style.opacity = '0';
      }
      function reveal(c) {
        if (!c) return;
        var row = c.querySelector('.msg-actions-row');
        if (!row) return;
        var wasOpen = row.getAttribute('data-open') === '1';
        _closeAllMsgActionRows();
        if (!wasOpen) {
          row.style.display = 'inline-flex';
          row.setAttribute('data-open', '1');
          // build 4.78: подсветка карточки, к которой относится открытое
          // меню — видно, какое именно сообщение выбрано, как в
          // Telegram/WhatsApp, а не только сам ряд иконок снизу.
          c.classList.add('msg-selected');
        }
      }
      function endGesture() {
        clearTimer();
        if (card && pid !== null) { try { card.releasePointerCapture(pid); } catch(e) {} }
        card = null; pid = null; axisLocked = false; swiping = false; revealed = false;
      }
      listEl.addEventListener('pointerdown', function(ev) {
        if (ev.pointerType === 'mouse' && ev.button !== 0) return;
        if (listEl.classList.contains('msg-list-selecting')) { card = null; return; } // build 4.81: в режиме множественного выбора жесты меню/свайпа не нужны — тап переключает чекбокс
        // build 4.92: раньше сюда же попадал [data-nick-click] (ник автора)
        // — а это довольно большая часть карточки (вся шапка). Вместе с
        // текстом (свой повод — выделение, см. build 4.79), кнопками и
        // цитатой-ответом, из-под удержания фактически выпадало почти всё,
        // кроме тонких промежутков между этими блоками — реально удержание
        // срабатывало где-то посередине карточки, между шапкой и текстом.
        // Тап по нику по-прежнему открывает профиль (для этого хватает и
        // короткого касания, до срабатывания таймера меню) — держать
        // ЗАЖАТЫМ ник теперь тоже можно, откроется то же меню действий.
        if (ev.target.closest('button, a, input, textarea, .msg-actions-row, .chat-reply-quote, .chat-msg-text')) { card = null; return; }
        var c = ev.target.closest(cardSelector);
        if (!c) { card = null; return; }
        card = c; pid = ev.pointerId; startX = ev.clientX; startY = ev.clientY;
        axisLocked = false; swiping = false; revealed = false;
        clearTimer();
        timer = setTimeout(function() {
          revealed = true;
          reveal(card);
          // build 4.83: раньше здесь ещё был setTimeout(...,400), который
          // сбрасывал этот флаг сам по себе через 400мс. Но клик-«призрак»
          // после долгого тапа на телефоне приходит не через 450мс (когда
          // сработал таймер меню), а когда палец реально отпускают — а
          // держат обычно ощутимо дольше. Если человек держал больше
          // ~850мс суммарно, флаг успевал сброситься ДО реального клика —
          // тогда клик доходил до глобального обработчика уже как обычный,
          // и меню, только что открывшееся, тут же закрывалось само (эффект
          // «появилось и сразу исчезло», тем чаще, чем дольше держат палец).
          // Теперь флаг живёт, пока его не «съест» следующий клик, сколько
          // бы времени это ни заняло — см. document click-обработчик ниже.
          // Отдельный маленький подстраховочный таймаут (5с, а не 400мс) —
          // на случай, если клик так и не придёт вовсе (например, жест
          // прервался pointercancel) и флаг иначе завис бы навсегда,
          // ошибочно проглотив совершенно другой клик когда-нибудь потом.
          _msgActionsSuppressClick = true;
          clearTimeout(_msgActionsSuppressClickSafety);
          _msgActionsSuppressClickSafety = setTimeout(function(){ _msgActionsSuppressClick = false; }, 5000);
          try { navigator.vibrate && navigator.vibrate(12); } catch(e) {}
        }, REVEAL_DURATION);
      });
      listEl.addEventListener('pointermove', function(ev) {
        if (!card || ev.pointerId !== pid || revealed) return;
        var dx = ev.clientX - startX, dy = ev.clientY - startY;
        if (!axisLocked) {
          if (Math.abs(dx) < DEAD_ZONE && Math.abs(dy) < DEAD_ZONE) return; // всё ещё похоже на удержание — не мешаем таймеру меню
          // Вышли за мёртвую зону — это уже точно не «удержание на месте»:
          // меню по долгому тапу больше не должно открыться этим жестом.
          clearTimer();
          axisLocked = true;
          var horizontalLeft = Math.abs(dx) > Math.abs(dy) && dx < 0;
          if (!horizontalLeft || !findReplyBtn(card)) return; // вертикальный скролл/свайп вправо/нечем отвечать — не наш случай, отдаём браузеру
          swiping = true;
          try { card.setPointerCapture(pid); } catch(e) {}
        }
        if (!swiping) return;
        ev.preventDefault();
        var off = Math.max(-SWIPE_REPLY_MAX, Math.min(0, dx));
        card.setAttribute('data-swiping', '1');
        card.style.transform = 'translateX(' + off + 'px)';
        var icon = card.querySelector('.chat-msg-swipe-reply-icon');
        if (icon) icon.style.opacity = String(Math.min(1, Math.abs(off) / SWIPE_REPLY_TRIGGER));
      }, { passive: false });
      function finish(ev) {
        if (!card || ev.pointerId !== pid) return;
        var c = card, wasSwiping = swiping;
        var dx = wasSwiping ? (ev.clientX - startX) : 0;
        var didTrigger = wasSwiping && dx <= -SWIPE_REPLY_TRIGGER;
        endGesture();
        if (wasSwiping) resetSwipeVisual(c, true);
        if (didTrigger) {
          var btn = findReplyBtn(c);
          if (btn) { try { navigator.vibrate && navigator.vibrate(10); } catch(e) {} btn.click(); }
        }
      }
      listEl.addEventListener('pointerup', finish);
      listEl.addEventListener('pointercancel', function(ev) {
        if (!card || ev.pointerId !== pid) return;
        var c = card, wasSwiping = swiping;
        endGesture();
        if (wasSwiping) resetSwipeVisual(c, false);
      });
      // Десктоп: правый клик — то же самое меню, без ожидания удержания.
      listEl.addEventListener('contextmenu', function(ev) {
        var c = ev.target.closest(cardSelector);
        if (!c) return;
        ev.preventDefault();
        reveal(c);
      });
    }
    function _audioCacheStats() {
      return _audioCacheOpenDB().then(function(db) {
        if (!db) return { count: 0, bytes: 0 };
        return new Promise(function(resolve) {
          try {
            var store = db.transaction('audio', 'readonly').objectStore('audio');
            var count = 0, bytes = 0;
            var cursorReq = store.openCursor();
            cursorReq.onsuccess = function(ev) {
              var cursor = ev.target.result;
              if (cursor) { count++; bytes += (cursor.value && cursor.value.size) || 0; cursor.continue(); }
              else resolve({ count: count, bytes: bytes });
            };
            cursorReq.onerror = function() { resolve({ count: 0, bytes: 0 }); };
          } catch(e) { resolve({ count: 0, bytes: 0 }); }
        });
      });
    }
    // ===== Офлайн-кэш самих сообщений (build 4.115) — раньше кэшировались
    // только фото (см. _imgCacheOpenDB выше), а текст переписки при
    // каждом открытии загружался заново из сети — без интернета список
    // сообщений был просто недоступен. Теперь после каждой успешной
    // онлайн-загрузки последний известный снимок переписки (до
    // MSG_CACHE_LIMIT сообщений) сохраняется в отдельную IndexedDB, и при
    // отсутствии сети (или ошибке запроса) чат открывается из этого
    // снимка — с явной пометкой «офлайн, показано последнее известное»,
    // без новых сообщений (их и не может быть без интернета) и без
    // возможности писать. Один общий кэш на все три типа чатов, ключ —
    // 'general' / 'dm:<partnerId>' / 'group:<groupId>'.
    var _msgCacheDB = null;
    var MSG_CACHE_LIMIT = 60;
    function _msgCacheOpenDB() {
      return new Promise(function(resolve) {
        if (_msgCacheDB) { resolve(_msgCacheDB); return; }
        if (!window.indexedDB) { resolve(null); return; }
        try {
          var req = indexedDB.open('quran_chat_msg_cache', 1);
          req.onupgradeneeded = function() { req.result.createObjectStore('conversations'); };
          req.onsuccess = function() { _msgCacheDB = req.result; resolve(_msgCacheDB); };
          req.onerror = function() { resolve(null); };
        } catch(e) { resolve(null); }
      });
    }
    // rows — массив сообщений в ЛЮБОМ порядке (сортируем сами по
    // created_at перед обрезкой), сохраняем только последние
    // MSG_CACHE_LIMIT — конкретное количество, не мегабайты: обычно это
    // десятки КБ текста, даже для активной переписки, никакого заметного
    // расхода места на устройстве.
    function _msgCacheSave(convKey, rows) {
      if (!rows || !rows.length) return;
      _msgCacheOpenDB().then(function(db) {
        if (!db) return;
        try {
          var sorted = rows.slice().sort(function(a,b){ return new Date(a.created_at) - new Date(b.created_at); });
          var trimmed = sorted.slice(-MSG_CACHE_LIMIT);
          db.transaction('conversations', 'readwrite').objectStore('conversations')
            .put({ rows: trimmed, cachedAt: Date.now() }, convKey);
        } catch(e) {}
      });
    }
    function _msgCacheLoad(convKey) {
      return _msgCacheOpenDB().then(function(db) {
        if (!db) return null;
        return new Promise(function(resolve) {
          try {
            var req = db.transaction('conversations', 'readonly').objectStore('conversations').get(convKey);
            req.onsuccess = function() { resolve(req.result || null); };
            req.onerror = function() { resolve(null); };
          } catch(e) { resolve(null); }
        });
      });
    }
    // Небольшая полоска-предупреждение над лентой сообщений — честно
    // говорит, что это не живые данные, а последнее, что успели загрузить,
    // пока была связь.
    function _msgCacheOfflineBannerHtml(kk, cachedAt) {
      var when = cachedAt ? new Date(cachedAt).toLocaleString(kk?'kk-KZ':'ru-RU', {day:'numeric', month:'long', hour:'2-digit', minute:'2-digit'}) : '';
      return '<div class="card" style="margin-bottom:0.5rem;padding:0.5rem 0.7rem;border-color:#e6a700">' +
        '<b>📴 '+(kk?'Офлайн':'Офлайн')+'</b> — '+(kk
          ? 'соңғы белгілі хабарламалар көрсетілген'+(when?' ('+when+' жүктелген)':'')+'. Жаңа хабарламалар интернет пайда болғанда көрінеді, жазу да сонда қолжетімді болады.'
          : 'показаны последние известные сообщения'+(when?' (загружены '+when+')':'')+'. Новые появятся, когда будет интернет — тогда же станет доступна и отправка.')+
      '</div>';
    }
    function _imgCacheGet(url) {
      return _imgCacheOpenDB().then(function(db) {
        if (!db) return null;
        return new Promise(function(resolve) {
          try {
            var tx = db.transaction('images', 'readonly');
            var req = tx.objectStore('images').get(url);
            req.onsuccess = function() { resolve(req.result || null); };
            req.onerror = function() { resolve(null); };
          } catch(e) { resolve(null); }
        });
      });
    }
    function _imgCacheSet(url, blob) {
      _imgCacheOpenDB().then(function(db) {
        if (!db) return;
        try { db.transaction('images', 'readwrite').objectStore('images').put(blob, url); } catch(e) {}
      });
    }
    // build 5.47: раньше (5.46) в лимит скачивания засчитывался КАЖДЫЙ
    // показ фото в ленте — в том числе те, что уже лежали в этом самом
    // кэше (IndexedDB, build 4.62) и с сервера на самом деле не грузились
    // вообще. Это давало неверную, завышенную картину — кэш ведь и
    // существует для того, чтобы повторный просмотр был бесплатным.
    // Теперь bytes считается ТОЛЬКО в ветке настоящего промаха кэша (там,
    // где реально идёт fetch(url) на сервер) — показ уже закэшированной
    // картинки (из _imgCacheMemUrls или из IndexedDB) в лимит не входит.
    // build 5.49: настоящая сетевая загрузка (была раньше внутри
    // _chatImgSrcCached целиком) — вынесена в отдельную функцию, чтобы
    // запускать её либо сразу (автозагрузка включена), либо только по
    // тапу пользователя, если в настройках «Автозагрузка фото»
    // выключена (см. _chatImgShowTapToLoad ниже).
    function _chatImgFetchAndShow(url, imgEl, bytes) {
      // Показываем как обычно с сервера, и в фоне сохраняем Blob на
      // будущее (следующее открытие этой же переписки/группы).
      imgEl.src = url;
      fetch(url).then(function(res) { return res.ok ? res.blob() : null; }).then(function(fetchedBlob) {
        if (fetchedBlob) {
          _imgCacheSet(url, fetchedBlob);
          _imgCacheMemUrls[url] = URL.createObjectURL(fetchedBlob);
          // Настоящая сетевая загрузка только что произошла — вот
          // единственное честное место засчитать её в личный/общий
          // лимит скачивания (см. build 5.45/5.46). Блокировать саму
          // картинку по-прежнему нельзя (см. комментарий у прежнего
          // обработчика 'load') — только считаем постфактум и
          // предупреждаем о порогах/превышении.
          var dlBytes = fetchedBlob.size || bytes || 0;
          if (dlBytes) {
            var kkNow = state.settings && state.settings.lang === 'kk';
            var sb = (typeof getSb === 'function') ? getSb() : null;
            var sess = (typeof authSession === 'function') ? authSession() : null;
            if (sb && sess && sess.userId) {
              _chatDownloadGate(sb, sess.userId, dlBytes, kkNow).then(function() {
                _downloadUsageRecord(sb, sess.userId, dlBytes);
              });
            }
          }
        }
      }).catch(function(){});
    }
    // build 5.49: настройка «Автозагрузка фото» выключена и фото ещё нет
    // в кэше устройства — вместо мгновенной загрузки (и траты лимита
    // скачивания) рисуем плейсхолдер поверх пустой миниатюры (у самого
    // <img> нет src — виден просто фон рамки). Тап по плейсхолдеру
    // запускает настоящую загрузку и сразу открывает фото на весь экран
    // (одним тапом, как и при включённой автозагрузке).
    function _chatImgShowTapToLoad(url, imgEl, bytes) {
      var wrap = imgEl.parentElement;
      if (!wrap) { _chatImgFetchAndShow(url, imgEl, bytes); return; } // на всякий случай — разметки без обёртки не бывает, но подстрахуемся
      var kkNow = state.settings && state.settings.lang === 'kk';
      var ph = document.createElement('div');
      ph.className = 'img-tap-to-load';
      ph.style.cssText = 'position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0.2rem;cursor:pointer;background:rgba(0,0,0,0.3);border-radius:0.5rem;color:#fff;text-align:center;padding:0.3rem';
      ph.innerHTML = '<span style="font-size:1.3rem">🖼️</span><span style="font-size:0.68rem;line-height:1.2">'+(kkNow?'Жүктеу үшін басыңыз':'Нажмите, чтобы загрузить')+(bytes?'<br>'+_chatFmtSize(bytes):'')+'</span>';
      ph.addEventListener('click', function(ev) {
        ev.stopPropagation();
        ph.remove();
        _chatImgFetchAndShow(url, imgEl, bytes);
        if (typeof openImgLightbox === 'function') openImgLightbox(url, bytes);
      });
      wrap.appendChild(ph);
    }
    function _chatImgSrcCached(url, imgEl, bytes) {
      if (!url) return;
      if (_imgCacheMemUrls[url]) { imgEl.src = _imgCacheMemUrls[url]; return; }
      _imgCacheGet(url).then(function(blob) {
        if (blob) {
          var objUrl = URL.createObjectURL(blob);
          _imgCacheMemUrls[url] = objUrl;
          imgEl.src = objUrl;
          return;
        }
        // Настоящий промах кэша — реальной загрузки с сервера ещё не
        // было. Если автозагрузка фото выключена в настройках, вместо
        // неё показываем плейсхолдер «Нажмите, чтобы загрузить» (тратит
        // лимит скачивания только по тапу); иначе — как раньше, сразу.
        if (!_photoAutoLoadOn()) {
          _chatImgShowTapToLoad(url, imgEl, bytes);
          return;
        }
        _chatImgFetchAndShow(url, imgEl, bytes);
      });
    }
    // Наблюдатель за списком сообщений — ловит и уже отрисованные, и вновь
    // добавленные (Realtime/подгрузка истории) картинки, не требуя правок
    // в местах, где сообщения вставляются в DOM (их много в трёх чатах).
    function _bindImageCacheObserver(listEl) {
      function processImg(img) {
        if (img._imgCacheBound) return;
        img._imgCacheBound = true;
        var url = img.getAttribute('data-lightbox-src');
        var bytes = parseInt(img.getAttribute('data-dl-bytes'), 10) || 0;
        if (url) _chatImgSrcCached(url, img, bytes);
      }
      listEl.querySelectorAll('img[data-lightbox-src]').forEach(processImg);
      if (!window.MutationObserver) return;
      var obs = new MutationObserver(function(mutations) {
        mutations.forEach(function(mut) {
          (mut.addedNodes || []).forEach(function(node) {
            if (node.nodeType !== 1) return;
            if (node.matches && node.matches('img[data-lightbox-src]')) processImg(node);
            if (node.querySelectorAll) node.querySelectorAll('img[data-lightbox-src]').forEach(processImg);
          });
        });
      });
      obs.observe(listEl, { childList: true, subtree: true });
    }
    function _chatTimeLabel(iso) {
      try {
        var d = new Date(iso);
        return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      } catch(e) { return ''; }
    }
    // ========== Вложение файлов в ЛС/группах (build 4.28) ==========
    // Раньше (4.25) можно было прикрепить ровно одну картинку. Теперь — до
    // CHAT_FILE_MAX_COUNT файлов за раз, любого типа (документы, аудио,
    // архивы и т.п.), кроме явно исполняемых форматов. Картинки в предпросмотре
    // и в самом сообщении показываются миниатюрой, остальные — карточкой
    // со скрепкой, именем и размером, тап открывает/скачивает файл.
    var CHAT_FILE_MAX_BYTES = 15 * 1024 * 1024; // build 4.99: было 100 МБ — на бесплatном тарифе Supabase (Storage ~1ГБ на весь сайт) это позволяло одним файлом съесть половину месячного личного лимита разом. 15 МБ разумно даже для видео-заметок и больших документов, а фото теперь всё равно сжимаются перед отправкой (см. _chatCompressImage) и почти никогда не подходят к этому потолку.
    var CHAT_FILE_MAX_COUNT = 5; // файлов за одно сообщение
    var CHAT_FILE_BLOCKED_EXT = ['exe','bat','cmd','sh','msi','apk','js','jar','com','scr','vbs','ps1','dll'];
    var CHAT_IMG_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
    function _chatFileExt(name) {
      var m = /\.([a-zA-Z0-9]{1,8})$/.exec(name || '');
      return m ? m[1].toLowerCase() : '';
    }
    function _chatIsImgFile(file) {
      return !!(file && CHAT_IMG_TYPES.indexOf(file.type) >= 0);
    }
    // build 4.109: настоящее сжатие видео в браузере — без тяжёлых
    // библиотек вроде ffmpeg.wasm (это лишние ~30 МБ загрузки и заметно
    // медленно на слабых телефонах) практически неосуществимо нормально —
    // WebCodecs/MediaRecorder не дают предсказуемого управления битрейтом
    // на всех устройствах. Честнее — не делать вид, что сжатие есть, а
    // просто предупредить о размере и подсказать, как его уменьшить самому
    // (записать покороче/не в 4K) — тем более что у видео обычно и так нет
    // выбора «сжать/оригинал», сама идея выбора тут неприменима. Для
    // остальных типов файлов (документы и т.п.) сжатие в браузере тоже, как
    // правило, бессмысленно — большинство таких форматов (PDF и т.п.) уже
    // эффективно упакованы форматом, реального выигрыша почти нет.
    function _chatWarnLargeVideo(file, kk) {
      if (!file || file.type.indexOf('video/') !== 0) return;
      if (file.size < 5 * 1024 * 1024) return; // до 5 МБ — не о чем предупреждать
      toast((kk
        ? 'Видео '+_chatFmtSize(file.size)+' — үлкен файл. Браузерде видеоны нақты сығу мүмкін емес (үлкен қосымша кітапхана қажет болар еді) — қысқарақ жазып көріңіз немесе сапасын төмендетіп қайта түсіріңіз.'
        : 'Видео '+_chatFmtSize(file.size)+' — большой файл. Реального сжатия видео в браузере, увы, нет (потребовалась бы тяжёлая дополнительная библиотека) — попробуйте записать покороче или в меньшем качестве.'), 5000);
    }
    // build 4.104: перед отправкой фото — спросить, сжимать или нет, и
    // показать реальную разницу в размере, а не абстрактно «сжатие
    // экономит место». Если среди вложений нет ни одной картинки (только
    // документы/голосовые), модалка вообще не появляется — пропускаем
    // сразу. Возвращает массив файлов, готовых к загрузке (для картинок —
    // либо уже сжатые, либо оригиналы, в зависимости от выбора; для
    // остального — как есть, без изменений).
    async function _chatConfirmCompression(files, kk) {
      var imgFiles = files.filter(_chatIsImgFile);
      if (!imgFiles.length) return files;
      // build 5.33: раньше тут всегда всплывало окно «Сжать / Оригинал» —
      // именно оно требовало лишнего тапа перед каждой отправкой фото.
      // Выбор теперь берётся из настройки «Мой аккаунт → 🗜️ Сжатие фото/
      // голосовых» (_mediaCompressOn(), по умолчанию включена): при
      // «Сжатое» фото пережимается молча, при «Оригинал» отправляется как
      // есть — без всплывающего окна на каждое сообщение. Сама настройка
      // и есть выбор, сделанный один раз, а не диалог на каждый файл.
      var compressedMap = new Map();
      for (var i = 0; i < imgFiles.length; i++) {
        try { compressedMap.set(imgFiles[i], await _chatCompressImage(imgFiles[i])); }
        catch(e) { compressedMap.set(imgFiles[i], imgFiles[i]); }
      }
      return files.map(function(f) {
        if (!_chatIsImgFile(f)) return f;
        return compressedMap.get(f);
      });
    }
    function _chatFmtSize(bytes) {
      if (!bytes && bytes !== 0) return '';
      if (bytes < 1024) return bytes + ' Б';
      if (bytes < 1024 * 1024) return Math.round(bytes / 1024) + ' КБ';
      return (Math.round(bytes / 1024 / 1024 * 10) / 10) + ' МБ';
    }
    function _chatValidateFile(file, kk) {
      if (!file) return null;
      var ext = _chatFileExt(file.name);
      if (CHAT_FILE_BLOCKED_EXT.indexOf(ext) >= 0) {
        return kk ? 'Бұл файл түрі рұқсат етілмеген' : 'Этот тип файла запрещён';
      }
      if (file.size > CHAT_FILE_MAX_BYTES) {
        return kk ? 'Файл тым үлкен (максимум 15 МБ)' : 'Файл слишком большой (максимум 15 МБ)';
      }
      return null;
    }
    // ===== Личный и общий лимит хранилища (build 4.99) — на бесплатном
    // тарифе Supabase место в Storage общее на весь сайт (около 1 ГБ),
    // поэтому нужно и следить за общим расходом, и не дать одному человеку
    // случайно (или специально) забить всё место. Учёт — отдельная
    // таблица storage_usage: одна строка на каждый загруженный файл, с
    // размером в байтах. Действующий расход — не «за всё время», а за
    // последние 30 дней: ровно то время, что сообщения и вложения вообще
    // хранятся (см. auto-purge ниже, SQL в записи журнала) — старые файлы
    // и так удаляются, а вместе с ними «освобождается» и место в чужом
    // личном лимите, никакого отдельного «сброса» делать не需要.
    var PERSONAL_STORAGE_QUOTA = 20 * 1024 * 1024;   // 20 МБ на человека
    var PERSONAL_STORAGE_QUOTA_ADMIN = 100 * 1024 * 1024; // build 4.109: админам — 100 МБ (модерация/тесты часто требуют больше вложений, чем обычной переписке)
    var SITE_STORAGE_BUDGET = 900 * 1024 * 1024;      // ~900 МБ — с запасом под потолок Supabase free (~1 ГБ), остальное — буфер под системные файлы
    function _myStorageQuota() {
      return ((typeof isAdminUser === 'function') && isAdminUser()) ? PERSONAL_STORAGE_QUOTA_ADMIN : PERSONAL_STORAGE_QUOTA;
    }
    // build 5.33: общий переключатель «сжатое / оригинал» для фото и
    // голосовых — «Мой аккаунт» → «Переписки» (та же синхронизируемая
    // state.settings, что и «Автозагрузка аудио»). По умолчанию (когда
    // настройка ещё не трогалась — undefined) считается ВКЛЮЧЕНО сжатие,
    // то есть ничего специально нажимать не нужно, чтобы отправить
    // сжатое — «обычное» нужно осознанно включить самому.
    function _mediaCompressOn() {
      return !(state && state.settings && state.settings.mediaCompress === false);
    }
    // build 5.49: настройка «Автозагрузка фото» (Мой аккаунт → Переписки) —
    // по умолчанию (undefined) включена, как и раньше; выключить нужно
    // осознанно самому, см. acc-photodl-mode выше по файлу.
    function _photoAutoLoadOn() {
      return !(state && state.settings && state.settings.photoAutoLoad === false);
    }
    // build 4.108: source — по умолчанию 'chat' (обычные вложения в
    // сообщениях, учитываются и в личном, и в общем лимите). Вложения к
    // обращениям в «💡🐞 Обратная связь» помечаются source='feedback' —
    // намеренно не в счёт личного лимита пользователя (нет смысла тратить
    // его на скриншот бага, который делается для пользы сайта, а не
    // личной переписки), но всё ещё учитываются в общем лимите сайта —
    // место есть место, следить за ним нужно в любом случае.
    async function _storageUsageRecord(sb, userId, path, bytes, source) {
      if (!bytes) return;
      await sb.from('storage_usage').insert({ user_id: userId, file_path: path, bytes: bytes, source: source || 'chat' });
    }
    async function _storageUsageGetMine(sb, userId) {
      try {
        var r = await sb.from('storage_usage').select('bytes').eq('user_id', userId).neq('source', 'feedback').gte('created_at', new Date(Date.now() - 30*24*60*60*1000).toISOString());
        if (r.error) return 0;
        return (r.data || []).reduce(function(sum, row){ return sum + (row.bytes || 0); }, 0);
      } catch(e) { return 0; }
    }
    async function _storageUsageGetSite(sb) {
      try {
        var r = await sb.from('storage_usage').select('bytes').gte('created_at', new Date(Date.now() - 30*24*60*60*1000).toISOString());
        if (r.error) return 0;
        return (r.data || []).reduce(function(sum, row){ return sum + (row.bytes || 0); }, 0);
      } catch(e) { return 0; }
    }
    // ===== Официальные лимиты бесплатного тарифа Supabase (build 5.36) —
    // отдельная панель в «📊 Хранилище», построенная по реальному
    // скриншоту тарифа $0/мес: unlimited API requests · 50 000 monthly
    // active users · 500 MB database · 5 GB egress + 5 GB cached egress ·
    // 1 GB file storage. Часть цифр честно берётся живыми запросами
    // (активные пользователи, файловое хранилище — у нас уже есть),
    // часть — НЕ измерима из браузера в принципе (сетевой трафик/egress
    // считает сама Supabase на своей стороне, публичного клиентского API
    // для этого нет) и показывается только как справочный лимит, без
    // придуманной цифры «использовано».
    var SUPA_FREE_MAU_LIMIT = 50000;
    var SUPA_FREE_DB_LIMIT_BYTES = 500 * 1024 * 1024;       // 500 МБ
    var SUPA_FREE_FILESTORAGE_LIMIT_BYTES = 1024 * 1024 * 1024; // 1 ГБ (официальный лимит; наш собственный SITE_STORAGE_BUDGET ниже него — это уже наш запас прочности, см. комментарий у SITE_STORAGE_BUDGET)
    var SUPA_FREE_EGRESS_LIMIT_BYTES = 5 * 1024 * 1024 * 1024;        // 5 ГБ
    var SUPA_FREE_CACHED_EGRESS_LIMIT_BYTES = 5 * 1024 * 1024 * 1024; // 5 ГБ (кэшированный, отдельно от обычного)
    // build 5.44/5.45: личный и общий лимит на СКАЧИВАНИЕ вложений —
    // сначала (5.44) был чисто справочным, теперь (5.45) реально
    // считается и блокирует: отдельная таблица download_usage, одна
    // строка на каждое явное скачивание (нажатие ⬇️ у фото/файла,
    // «Скачать и слушать» у голосового, первое воспроизведение
    // автозагружаемого голосового) — окно то же скользящее 30 дней, что
    // и у отправки (storage_usage). Это НЕ то же самое, что настоящий
    // egress-трафик Supabase (открытие самой страницы, её код, превью в
    // ленте тоже тратят трафик, но здесь не считаются) — честный счётчик
    // именно осознанных «скачиваний» через интерфейс приложения. Цифры
    // ниже можно изменить прямо в коде, поиском по файлу.
    var PERSONAL_DOWNLOAD_LIMIT_BYTES = 200 * 1024 * 1024; // 200 МБ на человека за 30 дней
    var SITE_DOWNLOAD_LIMIT_BYTES = SUPA_FREE_EGRESS_LIMIT_BYTES + SUPA_FREE_CACHED_EGRESS_LIMIT_BYTES; // с запасом в рамках общего egress-бюджета сайта (5+5 ГБ)
    async function _downloadUsageRecord(sb, userId, bytes) {
      if (!bytes || !userId) return;
      try { await sb.from('download_usage').insert({ user_id: userId, bytes: bytes }); } catch(e) { console.warn('download usage record', e); }
    }
    async function _downloadUsageGetMine(sb, userId) {
      try {
        var r = await sb.from('download_usage').select('bytes').eq('user_id', userId).gte('created_at', new Date(Date.now() - 30*24*60*60*1000).toISOString());
        if (r.error) return 0;
        return (r.data || []).reduce(function(sum, row){ return sum + (row.bytes || 0); }, 0);
      } catch(e) { return 0; }
    }
    async function _downloadUsageGetSite(sb) {
      try {
        var r = await sb.from('download_usage').select('bytes').gte('created_at', new Date(Date.now() - 30*24*60*60*1000).toISOString());
        if (r.error) return 0;
        return (r.data || []).reduce(function(sum, row){ return sum + (row.bytes || 0); }, 0);
      } catch(e) { return 0; }
    }
    async function _downloadUsageGetOldest(sb, userId) {
      try {
        var q = sb.from('download_usage').select('created_at').gte('created_at', new Date(Date.now() - 30*24*60*60*1000).toISOString()).order('created_at', { ascending: true }).limit(1);
        if (userId) q = q.eq('user_id', userId);
        var r = await q;
        if (r.error || !r.data || !r.data.length) return null;
        return new Date(r.data[0].created_at);
      } catch(e) { return null; }
    }
    // Проверка ПЕРЕД скачиванием — как и у отправки (_storageQuotaCheck),
    // но с двумя порогами: сначала личный, потом общий сайта. Возвращает
    // null, если скачивать можно, или готовый текст отказа.
    var _downloadWarnedThresholds = {};
    async function _downloadQuotaCheck(sb, userId, addBytes, kk) {
      var mine = await _downloadUsageGetMine(sb, userId);
      var afterMine = mine + (addBytes || 0);
      if (afterMine > PERSONAL_DOWNLOAD_LIMIT_BYTES) {
        var usedMb = (mine / 1024 / 1024).toFixed(1);
        var quotaMb = (PERSONAL_DOWNLOAD_LIMIT_BYTES / 1024 / 1024).toFixed(0);
        return kk
          ? 'Жеке скачау лимиті таусылды ('+usedMb+' МБ / '+quotaMb+' МБ). 30 күннен кейін өздігінен босайды.'
          : 'Личный лимит скачивания исчерпан ('+usedMb+' МБ / '+quotaMb+' МБ). Освободится сам через 30 дней.';
      }
      var site = await _downloadUsageGetSite(sb);
      var afterSite = site + (addBytes || 0);
      if (afterSite > SITE_DOWNLOAD_LIMIT_BYTES) {
        return kk
          ? 'Сайттың жалпы скачау лимиті осы сәтте таусылды. Сәлден соң қайталап көріңіз.'
          : 'Общий лимит скачивания сайта на этот момент исчерпан. Попробуйте чуть позже.';
      }
      var pct = afterMine / PERSONAL_DOWNLOAD_LIMIT_BYTES;
      var thresholds = [0.5, 0.75, 0.9];
      var crossed = null;
      thresholds.forEach(function(th) { if (pct >= th) crossed = th; });
      if (crossed !== null && !_downloadWarnedThresholds[crossed]) {
        thresholds.forEach(function(th) { if (th <= crossed) _downloadWarnedThresholds[th] = true; });
        var realPct = Math.round(pct * 100);
        toast(kk
          ? 'Жеке скачау лимитінің шамамен ' + realPct + '% пайдаланылды'
          : 'Использовано примерно ' + realPct + '% личного лимита скачивания');
      }
      return null;
    }
    // Обёртка: true — можно скачивать (и заодно показывает предупреждение
    // о порогах); false — уже показала toast с отказом, скачивание нужно
    // отменить. Неизвестный размер (старые сообщения без files[].size)
    // никогда не блокирует — просто не участвует в подсчёте.
    async function _chatDownloadGate(sb, userId, bytes, kk) {
      if (!bytes || !sb || !userId) return true;
      var msg = await _downloadQuotaCheck(sb, userId, bytes, kk);
      if (msg) { toast(msg); return false; }
      return true;
    }
    // Общая обёртка для мест скачивания: проверяет лимит, при успехе
    // выполняет само скачивание (doFn) и только потом пишет в учёт —
    // чтобы неудавшаяся/отменённая попытка не портила счётчик.
    async function _chatDownloadProceed(sb, userId, bytes, kk, doFn) {
      var ok = await _chatDownloadGate(sb, userId, bytes, kk);
      if (!ok) return;
      try { doFn(); } catch(e) {}
      if (bytes && sb && userId) { try { await _downloadUsageRecord(sb, userId, bytes); } catch(e) {} }
    }
    // «Активные пользователи» — честная замена официальному MAU: считаем
    // тех, у кого profiles.last_seen_at обновлялся за последние 30 дней
    // (это поле и так пишется на каждый реальный визит, см. build 4.61 —
    // «profiles.last_seen_at обновляем сами себе, пока вкладка реально
    // открыта»). Это не гарантированно то же самое число, что видит сама
    // Supabase (у неё MAU — по любому авторизованному запросу к их API,
    // шире, чем просто открытая вкладка), но ближайшее, что можно честно
    // получить из клиента без доступа к их внутренней статистике.
    async function _activeUsersGetCount(sb) {
      try {
        var r = await sb.from('profiles').select('id', { count: 'exact', head: true })
          .gte('last_seen_at', new Date(Date.now() - 30*24*60*60*1000).toISOString());
        if (r.error) return null;
        return typeof r.count === 'number' ? r.count : null;
      } catch(e) { return null; }
    }
    // Реальный размер базы данных — Supabase не отдаёт его напрямую через
    // обычный select-запрос, нужна отдельная SQL-функция (pg_database_size),
    // которую выполняет сама база. Функция ниже сначала создаётся один раз
    // в Supabase (см. запись в журнале обновлений/для админа), а отсюда
    // просто вызывается через RPC. Если функции ещё нет (SQL не выполнен) —
    // тихо возвращаем null, и на экране вместо цифры честно показывается
    // «неизвестно», а не выдуманное число.
    //   create or replace function public.get_db_size_bytes()
    //   returns bigint language sql security definer as $$
    //     select pg_database_size(current_database());
    //   $$;
    //   grant execute on function public.get_db_size_bytes() to authenticated, anon;
    async function _dbSizeGetBytes(sb) {
      try {
        var r = await sb.rpc('get_db_size_bytes');
        if (r.error || typeof r.data !== 'number') return null;
        return r.data;
      } catch(e) { return null; }
    }
    // build 4.109: лимит — не фиксированный «сброс раз в месяц», а
    // скользящее окно в 30 дней (у каждого файла свой личный «день
    // истечения», см. комментарий выше). Единой даты сброса поэтому не
    // существует — вместо неё показываем дату САМОГО СТАРОГО файла,
    // который сейчас засчитывается в лимит: именно он «выпадет» из
    // подсчёта первым, освободив часть места. Дальше место продолжит
    // освобождаться постепенно, файл за файлом, а не разом.
    async function _storageUsageGetOldest(sb, userId) {
      try {
        var q = sb.from('storage_usage').select('created_at').gte('created_at', new Date(Date.now() - 30*24*60*60*1000).toISOString()).order('created_at', { ascending: true }).limit(1);
        if (userId) q = q.eq('user_id', userId).neq('source', 'feedback');
        var r = await q;
        if (r.error || !r.data || !r.data.length) return null;
        return new Date(r.data[0].created_at);
      } catch(e) { return null; }
    }
    // build 4.110: важное уточнение (задан прямой вопрос — насколько это
    // точно). Дата НЕ гадание: это ровно «дата самой старой учтённой
    // загрузки + 30 дней», простая математика. Важно понимать разницу:
    // — Личный лимит (можно ли отправлять) всегда считается заново по
    //   этой же формуле прямо в запросе (см. _storageUsageGetMine — там
    //   .gte('created_at', now-30 дней)), поэтому лимит гарантированно
    //   разблокируется именно в это время НЕЗАВИСИМО от того, успела ли
    //   в Supabase реально отработать автоочистка (pg_cron) — старое само
    //   перестаёт считаться, как только ему стукнуло 30 дней, что бы ни
    //   происходило на сервере в фоне.
    // — А вот РЕАЛЬНОЕ удаление файлов из Storage (то, что физически
    //   освобождает место у Supabase, а не только «не считается лично
    //   вам») — это отдельный процесс, тот самый pg_cron из записи 4.99.
    //   Если он по какой-то причине не работает на вашем тарифе — старые
    //   файлы физически останутся висеть в Storage (это уже касается
    //   общего лимита сайта, не личной блокировки отправки), поэтому
    //   стоит иногда проверять руками: select public.purge_old_chat_data();
    function _storageResetLabel(oldestDate, kk) {
      if (!oldestDate) return '';
      var freeAt = new Date(oldestDate.getTime() + 30*24*60*60*1000);
      var msLeft = freeAt - Date.now();
      if (msLeft <= 0) return '';
      var daysLeft = Math.ceil(msLeft / (24*60*60*1000));
      var dateStr = freeAt.toLocaleDateString(kk ? 'kk-KZ' : 'ru-RU', { day: 'numeric', month: 'long' });
      var timeStr = freeAt.toLocaleTimeString(kk ? 'kk-KZ' : 'ru-RU', { hour: '2-digit', minute: '2-digit' });
      return kk
        ? 'Келесі босату: '+dateStr+', '+timeStr+' («'+daysLeft+' күн қалды»)'
        : 'Ближайшее освобождение места: '+dateStr+', '+timeStr+' (осталось '+daysLeft+' '+(daysLeft===1?'день':(daysLeft<5?'дня':'дней'))+')';
    }
    // Проверка ПЕРЕД отправкой — возвращает null, если можно отправлять,
    // или готовый текст отказа, если личный лимит будет превышен. Заодно,
    // если после отправки будет пройден порог 50/75/90% — показывает
    // предупреждение (не блокирует, просто уведомляет), не чаще одного
    // раза за порог за сессию (см. _storageWarnedThresholds).
    var _storageWarnedThresholds = {};
    async function _storageQuotaCheck(sb, userId, addBytes, kk) {
      var quota = _myStorageQuota();
      var mine = await _storageUsageGetMine(sb, userId);
      var after = mine + (addBytes || 0);
      if (after > quota) {
        var usedMb = (mine / 1024 / 1024).toFixed(1);
        var quotaMb = (quota / 1024 / 1024).toFixed(0);
        return kk
          ? 'Жеке сақтау лимиті таусылды ('+usedMb+' МБ / '+quotaMb+' МБ). Ескі хабарламалар 30 күннен кейін өздігінен жойылғанда орын босайды.'
          : 'Личный лимит хранилища исчерпан ('+usedMb+' МБ / '+quotaMb+' МБ). Место освободится само, когда старые сообщения удалятся через 30 дней.';
      }
      var pct = after / quota;
      // build 5.33: раньше в тосте показывался номер сработавшего порога
      // (50/75/90), а не реальный процент — при резком скачке сразу за
      // 90% порог 0.75 оставался непомеченным «предупреждён» (цикл
      // .some() останавливался на первом совпадении), и при следующей
      // отправке мог показаться тост «75%», хотя по факту занято уже
      // больше 90%. Теперь показывается настоящий процент, а при первом
      // же уведомлении сразу помечаются «предупреждён» все пройденные
      // пороги — ниже сработавшего тост больше никогда не покажет.
      var thresholds = [0.5, 0.75, 0.9];
      var crossed = null;
      thresholds.forEach(function(th) { if (pct >= th) crossed = th; });
      if (crossed !== null && !_storageWarnedThresholds[crossed]) {
        thresholds.forEach(function(th) { if (th <= crossed) _storageWarnedThresholds[th] = true; });
        var realPct = Math.round(pct * 100);
        toast((kk
          ? 'Жеке сақтау лимитінің шамамен ' + realPct + '% пайдаланылды'
          : 'Использовано примерно ' + realPct + '% личного лимита хранилища'));
      }
      return null;
    }
    // Обёртка для мест отправки — сразу показывает toast и возвращает
    // false, если отправлять нельзя (личный лимит будет превышен).
    async function _chatQuotaGate(sb, userId, addBytes, kk) {
      var msg = await _storageQuotaCheck(sb, userId, addBytes, kk);
      if (msg) { toast(msg); return false; }
      return true;
    }
    // Загружает файл в публичный (на чтение) Supabase Storage-бакет
    // chat-files, папка — по id отправителя. Возвращает {url,name,type,size}.
    // build 4.99: перед загрузкой фото пережимается на клиенте (см.
    // _chatCompressImage чуть ниже) — на бесплатном Supabase Storage место
    // ограничено на весь сайт разом, а несжатые фото с телефона обычно
    // весят 2–5 МБ каждое при том, что для показа в чате достаточно
    // 1600px по длинной стороне.
    async function _chatCompressImage(file) {
      // GIF не трогаем — пережатие через canvas убьёт анимацию, превратив
      // gif в один статичный кадр. Уже небольшие файлы тоже не трогаем —
      // возиться с пережатием ради экономии в пару КБ смысла нет, а
      // качество только потеряется.
      if (!file || file.type === 'image/gif' || file.size < 250 * 1024) return file;
      if (!_mediaCompressOn()) return file; // build 5.33: пользователь выбрал «оригинал» в настройках
      try {
        var bitmap = await createImageBitmap(file);
        var MAX_SIDE = 1600;
        var w = bitmap.width, h = bitmap.height;
        if (w > MAX_SIDE || h > MAX_SIDE) {
          var scale = MAX_SIDE / Math.max(w, h);
          w = Math.round(w * scale);
          h = Math.round(h * scale);
        }
        var canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        var ctx = canvas.getContext('2d');
        ctx.drawImage(bitmap, 0, 0, w, h);
        var blob = await new Promise(function(resolve) { canvas.toBlob(resolve, 'image/jpeg', 0.82); });
        if (!blob || blob.size >= file.size) return file; // сжатие не помогло (редко, но бывает у уже оптимизированных PNG) — отправляем оригинал
        var newName = (file.name || 'photo').replace(/\.[a-zA-Z0-9]+$/, '') + '.jpg';
        return new File([blob], newName, { type: 'image/jpeg', lastModified: Date.now() });
      } catch(e) {
        return file; // createImageBitmap/canvas не сработали (старый браузер и т.п.) — отправляем как есть, не блокируем отправку
      }
    }
    async function _chatUploadFile(sb, userId, file, skipCompress, usageSource) {
      if (!skipCompress && _chatIsImgFile(file)) file = await _chatCompressImage(file);
      var ext = _chatFileExt(file.name) || 'bin';
      var path = userId + '/' + Date.now() + '_' + Math.random().toString(36).slice(2, 8) + '.' + ext;
      var up = await sb.storage.from('chat-files').upload(path, file, { cacheControl: '3600', upsert: false, contentType: file.type || 'application/octet-stream' });
      if (up && up.error) throw new Error(up.error.message || 'upload failed');
      var pub = sb.storage.from('chat-files').getPublicUrl(path);
      var url = pub && pub.data && pub.data.publicUrl;
      if (!url) throw new Error('no public url');
      // build 4.99: учёт использования личного/общего лимита хранилища —
      // см. _storageUsageRecord ниже. Не блокирует отправку при сбое (сама
      // загрузка уже прошла успешно) — только логирует предупреждение.
      try { await _storageUsageRecord(sb, userId, path, file.size || 0, usageSource); } catch(e) { console.warn('storage usage record', e); }
      return { url: url, name: file.name || ('file.' + ext), type: file.type || '', size: file.size || 0, _storagePath: path };
    }
    // Достаёт путь внутри бакета chat-files из полного публичного URL.
    function _chatStoragePathFromUrl(url) {
      if (!url) return null;
      var m = /\/chat-files\/(.+)$/.exec(url);
      return m ? m[1] : null;
    }
    // build 4.103: раньше «Очистить чат» удаляла только сами строки
    // сообщений (chat_messages/group_messages) — сами файлы (фото/
    // голосовые) в Storage оставались висеть осиротевшими, и место в
    // личном и общем лимите («📊 Хранилище») никак не освобождалось,
    // хотя видимых сообщений с этими вложениями уже не было. Теперь перед
    // удалением сообщений сначала собираются все пути вложений и удаляются
    // из Storage + из учёта storage_usage — лимит после очистки чата
    // реально уменьшается, а не просто «выглядит очищенным».
    async function _purgeMessagesStorage(sb, rows) {
      var paths = [];
      (rows || []).forEach(function(m) {
        if (m.files && m.files.length) {
          m.files.forEach(function(f) { var p = _chatStoragePathFromUrl(f.url); if (p) paths.push(p); });
        }
        if (m.image_url) { var p2 = _chatStoragePathFromUrl(m.image_url); if (p2) paths.push(p2); }
      });
      if (!paths.length) return;
      try { await sb.storage.from('chat-files').remove(paths); } catch(e) { console.warn('storage remove', e); }
      try { await sb.from('storage_usage').delete().in('file_path', paths); } catch(e) { console.warn('storage_usage cleanup', e); }
    }
    // build 4.104: общая модалка «Очистить с выбором» — теперь не только у
    // ЛС, но и у общего чата и групп: у любого пользователя есть личный
    // вариант «Только у себя» (прячет сообщения в его собственном списке,
    // ни на кого больше не влияет, место в лимите не освобождается —
    // данные никуда не делись), а «Для всех» — только там, где на это
    // есть право (общий чат — только сайт-админ; группа — создатель/
    // модератор; ЛС — вообще без прав, раз участников всего двое).
    function _chatOpenClearChoiceModal(opts) {
      var kk = opts.kk;
      var ex = document.getElementById('chat-clear-choice-modal');
      if (ex) ex.remove();
      var box = document.createElement('div');
      box.id = 'chat-clear-choice-modal';
      box.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:center;justify-content:center;padding:1rem';
      // build 4.106: раньше текст был жёстко зашит под «очистить
      // переписку» — при переиспользовании этой же модалки для «покинуть/
      // удалить группу» формулировка вводила в заблуждение («сообщения не
      // удаляются» звучит странно, когда на самом деле речь о выходе из
      // группы). Теперь заголовок и оба описания можно переопределить
      // через opts — если не передали, используются прежние формулировки
      // (для чатов).
      var titleTxt = opts.title || (kk ? 'Тазарту' : 'Очистить');
      var meLabel = opts.meLabel || (kk ? 'Тек өзіме' : 'Только для себя');
      var meDesc = opts.meDesc || (kk
        ? 'Тек сіздің тізіміңізде жасырылады. Басқалар үшін ештеңе өзгермейді, хабарламалар физикалық түрде жойылмайды — жеке лимитіңіз кемімейді.'
        : 'Скрывается только у вас. Для остальных ничего не меняется, сообщения физически не удаляются — ваш личный лимит места не уменьшится.');
      var allLabel = opts.allLabel || (kk ? 'Барлығы үшін' : 'Для всех');
      var allDesc = opts.allDesc || (kk
        ? 'Хабарламалар мен қоса тіркелген файлдар МӘҢГІ жойылады — барлығында. Орын лимиті нақты азаяды.'
        : 'Сообщения и вложения удаляются НАВСЕГДА — у всех. Лимит места реально уменьшится.');
      box.innerHTML =
        '<div class="card" style="max-width:22rem;width:100%">' +
          '<div style="display:flex;justify-content:space-between;align-items:center">' +
            '<b>🧹 '+titleTxt+'</b>' +
            '<button type="button" id="ccc-close" class="btn btn-sm" style="padding:0.15rem 0.55rem">✕</button>' +
          '</div>' +
          '<button type="button" id="ccc-me" class="btn btn-sm" style="width:100%;margin-top:0.7rem;text-align:left">👤 '+meLabel+'</button>' +
          '<div style="font-size:0.75rem;color:var(--text-muted);margin:0.25rem 0 0.6rem">'+meDesc+'</div>' +
          (opts.canClearForAll ? (
            '<button type="button" id="ccc-all" class="btn btn-sm" style="width:100%;color:var(--danger);text-align:left">👥 '+allLabel+'</button>' +
            '<div style="font-size:0.75rem;color:var(--text-muted);margin-top:0.25rem">'+allDesc+'</div>'
          ) : '') +
        '</div>';
      document.body.appendChild(box);
      box.addEventListener('click', function(ev){ if (ev.target === box) box.remove(); });
      document.getElementById('ccc-close').addEventListener('click', function(){ box.remove(); });

      document.getElementById('ccc-me').addEventListener('click', async function() {
        var btn = this; btn.disabled = true;
        try {
          await opts.onlyMeFn();
          toast(kk ? 'Тек сізде тазаланды' : 'Очищено только у вас');
          box.remove();
          if (typeof opts.onCleared === 'function') opts.onCleared();
        } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); btn.disabled = false; }
      });

      if (opts.canClearForAll) {
        document.getElementById('ccc-all').addEventListener('click', async function() {
          if (!confirm(kk ? 'Барлығы үшін МӘҢГІ жойылады. Растайсыз ба?' : 'Удалится НАВСЕГДА у всех. Точно?')) return;
          var btn = this; btn.disabled = true;
          try {
            await opts.forAllFn();
            toast(kk ? 'Барлығы үшін тазаланды' : 'Очищено у всех');
            box.remove();
            if (typeof opts.onCleared === 'function') opts.onCleared();
          } catch(e) { toast((kk?'Қате: ':'Ошибка: ')+(e.message||e)); btn.disabled = false; }
        });
      }
    }
    // HTML-блок картинки внутри уже отрисованного сообщения (превью с открытием
    // на весь экран по тапу — см. делегированный обработчик [data-lightbox-src] ниже).
    // Оставлен для обратной совместимости со старыми сообщениями (build 4.25),
    // у которых картинка лежит в image_url, а не в files[].
    function _chatImgBlockHtml(url) {
      if (!url) return '';
      var esc = _chatEsc(url);
      // build 4.34: у фото не было способа сохранить его на устройство —
      // только полноэкранный просмотр по тапу. Добавлена маленькая кнопка
      // ⬇️ поверх миниатюры (свой клик, не открывает лайтбокс) и такая же
      // кнопка внутри самого лайтбокса.
      return '<div style="margin-top:0.35rem;position:relative;display:inline-block">' +
        '<img data-lightbox-src="' + esc + '" data-dl-bytes="0" loading="lazy" alt="" style="max-width:220px;max-height:220px;border-radius:0.5rem;cursor:zoom-in;display:block;border:1px solid var(--border);background:var(--bg-card, rgba(127,127,127,0.08))" width="220" height="220">' +
        '<a href="' + esc + '" download class="dl-track-btn" data-dl-bytes="0" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="Скачать" style="position:absolute;bottom:0.35rem;right:0.35rem;background:rgba(0,0,0,0.55);color:#fff;border-radius:50%;width:1.7rem;height:1.7rem;display:flex;align-items:center;justify-content:center;font-size:0.9rem;text-decoration:none">⬇️</a>' +
      '</div>';
    }
    // Блок нескольких вложений (build 4.28) — картинки миниатюрами в ряд
    // (тап открывает на весь экран через тот же [data-lightbox-src]),
    // остальные файлы — карточкой со скрепкой, именем и размером; тап
    // открывает/скачивает файл в новой вкладке.
    // build 4.90: msgMeta — { id, source } (source: 'general'|'dm'|'group'),
    // нужен только для голосовых, чтобы кнопка «📝 Текст» знала, за какое
    // именно сообщение просить расшифровку (кэш — таблица voice_transcripts,
    // см. _voiceTranscribeFetch ниже). Параметр необязательный — старые
    // вызовы без него просто не покажут кнопку расшифровки.
    // build 4.105: раньше присланное через Realtime сообщение с фото
    // рендерилось нормально только после ручного обновления страницы (то
    // есть при обычной загрузке через select, которая гарантированно
    // отдаёт files уже разобранным массивом объектов) — а «живьём», через
    // postgres_changes, в редких случаях (например, при определённых
    // версиях клиента/сети) jsonb-колонка могла прийти НЕ разобранной, то
    // есть текстовой JSON-строкой вместо массива. files.length у строки —
    // это просто её длина в символах (не 0), поэтому ранняя проверка
    // "!files.length" не срабатывала, и следующий же files.filter(...)
    // ронял необработанное исключение прямо посреди сборки HTML карточки
    // — вся функция _chatMessageHtml обрывалась, не долистав до конца, и
    // новое сообщение с фото просто не попадало в DOM (текстовые
    // сообщения, у которых files=null, эту ветку вообще не затрагивали —
    // отсюда и разница «текст сразу виден, фото нет»). Теперь на входе
    // сначала пытаемся понять, не строка ли это, и разбираем сами.
    function _chatNormalizeFiles(files) {
      if (!files) return null;
      if (typeof files === 'string') {
        try { var parsed = JSON.parse(files); return Array.isArray(parsed) ? parsed : null; } catch(e) { return null; }
      }
      return Array.isArray(files) ? files : null;
    }
    function _chatFilesBlockHtml(files, msgMeta) {
      files = _chatNormalizeFiles(files);
      if (!files || !files.length) return '';
      var imgs = files.filter(function(f) { return f && f.type && f.type.indexOf('image/') === 0; });
      var audios = files.filter(function(f) { return f && f.type && f.type.indexOf('audio/') === 0; });
      var others = files.filter(function(f) {
        return !(f && f.type && (f.type.indexOf('image/') === 0 || f.type.indexOf('audio/') === 0));
      });
      var html = '';
      if (imgs.length) {
        html += '<div style="display:flex;flex-wrap:wrap;gap:0.35rem;margin-top:0.35rem">' +
          imgs.map(function(f) {
            var esc = _chatEsc(f.url);
            var szAttr = String(f.size || 0);
            return '<div style="position:relative;display:inline-block">' +
              '<img data-lightbox-src="' + esc + '" data-dl-bytes="' + szAttr + '" loading="lazy" alt="" style="max-width:150px;max-height:150px;border-radius:0.5rem;cursor:zoom-in;display:block;border:1px solid var(--border);background:var(--bg-card, rgba(127,127,127,0.08))" width="150" height="150">' +
              '<a href="' + esc + '" download class="dl-track-btn" data-dl-bytes="' + szAttr + '" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="Скачать" style="position:absolute;bottom:0.3rem;right:0.3rem;background:rgba(0,0,0,0.55);color:#fff;border-radius:50%;width:1.5rem;height:1.5rem;display:flex;align-items:center;justify-content:center;font-size:0.8rem;text-decoration:none">⬇️</a>' +
            '</div>';
          }).join('') + '</div>';
      }
      // Голосовые сообщения (build 4.45, перенесено из более ранней сборки) —
      // отдельным плеером <audio controls>, а не карточкой «скачать файл»,
      // как обычный документ. duration (сек, записанные через диктофон в
      // приложении) — просто подпись рядом, сам плеер и так покажет ход
      // воспроизведения.
      if (audios.length) {
        var kkA = state.settings && state.settings.lang === 'kk';
        html += '<div style="margin-top:0.35rem;display:flex;flex-direction:column;gap:0.35rem">' +
          audios.map(function(f) {
            var durLabel = f.duration ? _voiceDurLabel(f.duration) : '';
            // build 4.89: скорость воспроизведения — родной <audio controls>
            // такое умеет только через системное меню браузера (не на всех
            // платформах вообще есть), поэтому отдельная кнопка рядом. build
            // 4.97: раньше кнопка просто переключала по кругу 1×→1.5×→2×
            // по клику — по просьбе пользователя теперь открывает меню с
            // явным выбором из 0.5×/0.75×/1×/1.25×/1.5×/2× (см. общий
            // делегированный обработчик клика по .voice-speed-btn ниже по
            // файлу, документ level).
            var transcribeBtnHtml = '';
            // build 4.90: расшифровка голосового в текст — кнопка есть только
            // если у файла известно сообщение-владелец (msgMeta), иначе
            // некуда положить кэш результата. Сам текст, если уже
            // расшифрован f.transcript (пришёл вместе с сообщением при
            // повторном рендере — см. _voiceTranscribeFetch), показан сразу.
            if (msgMeta && msgMeta.id) {
              transcribeBtnHtml =
                '<button type="button" class="voice-transcribe-btn" data-url="'+_chatEsc(f.url)+'" data-mid="'+_chatEsc(msgMeta.id)+'" data-source="'+_chatEsc(msgMeta.source||'general')+'" title="'+(kkA?'Мәтінге түрлендіру':'Расшифровать в текст')+'" style="flex-shrink:0;background:var(--bg-card);border:1px solid var(--border);border-radius:0.4rem;padding:0.15rem 0.4rem;font-size:0.72rem;color:var(--text);cursor:pointer">📝</button>';
            }
            // build 4.100: настройка «Мой аккаунт → Автозагрузка аудио».
            // Выключена — вместо живого плеера показываем кнопку «⬇️
            // Скачать и слушать»: видно, что пришло голосовое и сколько
            // оно длится, но сам файл не начинает грузиться, пока не
            // нажали именно эту кнопку явно (полезно на мобильном
            // интернете или при осторожном отношении к личному лимиту
            // места — см. «📊 Хранилище»).
            var autoDl = !(state.settings && state.settings.voiceAutoDownload === false);
            if (!autoDl) {
              return '<div style="display:flex;align-items:center;gap:0.4rem">' +
                '<button type="button" class="voice-manual-load-btn" data-url="'+_chatEsc(f.url)+'" data-dl-bytes="'+(f.size||0)+'" style="flex:1;max-width:190px;background:var(--bg-card);border:1px solid var(--border);border-radius:0.4rem;padding:0.35rem 0.6rem;font-size:0.8rem;color:var(--text);cursor:pointer;text-align:left">⬇️ '+(kkA?'Жүктеп алу':'Скачать и слушать')+(durLabel?' · '+durLabel:'')+'</button>' +
                transcribeBtnHtml +
              '</div>';
            }
            return '<div style="display:flex;flex-direction:column;gap:0.25rem">' +
              '<div style="display:flex;align-items:center;gap:0.4rem">' +
                '<audio controls preload="none" src="' + _chatEsc(f.url) + '" data-dl-bytes="'+(f.size||0)+'" style="height:2.2rem;max-width:190px;flex:1"></audio>' +
                '<button type="button" class="voice-speed-btn" data-rate="1" title="'+(kkA?'Жылдамдық':'Скорость воспроизведения')+'" style="flex-shrink:0;background:var(--bg-card);border:1px solid var(--border);border-radius:0.4rem;padding:0.15rem 0.4rem;font-size:0.72rem;color:var(--text);cursor:pointer;min-width:2.4rem">1×</button>' +
                transcribeBtnHtml +
                (durLabel ? '<span style="font-size:0.72rem;color:var(--text-muted);flex-shrink:0">'+durLabel+'</span>' : '') +
              '</div>' +
              (f.transcript ? '<div class="voice-transcript-text" style="font-size:0.82rem;color:var(--text);background:var(--bg-card, rgba(127,127,127,0.08));border-radius:0.4rem;padding:0.35rem 0.5rem;white-space:pre-wrap">📝 '+_chatEsc(f.transcript)+'</div>' : '') +
            '</div>';
          }).join('') + '</div>';
      }
      if (others.length) {
        html += '<div style="margin-top:0.35rem;display:flex;flex-direction:column;gap:0.3rem">' +
          others.map(function(f) {
            // download="..." — без этого атрибута браузер у некоторых типов
            // файлов (например .docx) просто пытался открыть файл онлайн
            // через встроенный просмотрщик и не давал именно сохранить его
            // на устройство. С download браузер сразу сохраняет файл под
            // его исходным именем, как обычное скачивание.
            return '<a href="' + _chatEsc(f.url) + '" download="' + _chatEsc(f.name || '') + '" class="dl-track-btn" data-dl-bytes="'+(f.size||0)+'" target="_blank" rel="noopener" style="display:flex;align-items:center;gap:0.45rem;padding:0.35rem 0.55rem;border:1px solid var(--border);border-radius:0.5rem;color:var(--text);text-decoration:none;font-size:0.82rem">' +
              '<span style="font-size:1.1rem;flex-shrink:0">📄</span>' +
              '<span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + _chatEsc(f.name || '') + '</span>' +
              '<span style="color:var(--text-muted);font-size:0.75rem;white-space:nowrap;flex-shrink:0">' + _chatFmtSize(f.size) + '</span>' +
              '<span style="font-size:1rem;flex-shrink:0" title="'+'Скачать'+'">⬇️</span>' +
            '</a>';
          }).join('') + '</div>';
      }
      return html;
    }
    // build 4.90: расшифровка голосового сообщения в текст — доступность для
    // тех, кто не может сейчас слушать (шумно вокруг, нет наушников и т.п.),
    // плюс просто быстрее прочитать, чем прослушивать. Сама расшифровка
    // делается не в браузере (Web Speech API умеет распознавать только живой
    // звук с микрофона, а не уже записанный файл) — запрос уходит в Supabase
    // Edge Function 'transcribe-voice', которая пересылает аудио во внешний
    // сервис распознавания речи. Результат кэшируется в таблице
    // voice_transcripts (SQL и код самой Edge Function — см. запись 4.91
    // admin), чтобы одно и то же голосовое не расшифровывалось повторно ни
    // у того же, ни у другого читателя сообщения.
    async function _voiceTranscribeFetch(btn) {
      var url = btn.getAttribute('data-url');
      var mid = btn.getAttribute('data-mid');
      var source = btn.getAttribute('data-source') || 'general';
      var kk = state.settings && state.settings.lang === 'kk';
      var sb = getSb();
      if (!sb) { toast(kk?'Тек онлайн-режимде қолжетімді':'Доступно только в онлайн-режиме'); return; }
      var wrap = btn.closest('div[style*="flex-direction:column"]');
      btn.disabled = true;
      var origHtml = btn.innerHTML;
      btn.innerHTML = '⏳';
      function showResult(text) {
        var existing = wrap ? wrap.querySelector('.voice-transcript-text') : null;
        var block = '<div class="voice-transcript-text" style="font-size:0.82rem;color:var(--text);background:var(--bg-card, rgba(127,127,127,0.08));border-radius:0.4rem;padding:0.35rem 0.5rem;white-space:pre-wrap">📝 '+_chatEsc(text)+'</div>';
        if (existing) existing.outerHTML = block;
        else if (wrap) wrap.insertAdjacentHTML('beforeend', block);
        btn.innerHTML = origHtml;
        btn.disabled = false;
      }
      try {
        // 1) уже расшифровано кем-то раньше — берём из кэша, без повторного
        // обращения к платному сервису распознавания.
        var cacheRes = await sb.from('voice_transcripts').select('text').eq('source', source).eq('message_id', mid).eq('file_url', url).maybeSingle();
        if (cacheRes && !cacheRes.error && cacheRes.data && cacheRes.data.text) {
          showResult(cacheRes.data.text);
          return;
        }
      } catch(e) { /* таблицы может ещё не быть — просто пробуем расшифровать заново ниже */ }
      try {
        var fnRes = await sb.functions.invoke('transcribe-voice', { body: { url: url, lang: kk ? 'kk' : 'ru' } });
        if (fnRes && fnRes.error) throw new Error(fnRes.error.message || 'transcribe error');
        var text = fnRes && fnRes.data && fnRes.data.text;
        if (!text) throw new Error('empty transcript');
        showResult(text);
        // сохраняем в общий кэш «в фоне», не блокируя отклик — если функция
        // ещё не развёрнута или таблицы нет, ошибка молча проглатывается.
        try {
          sb.from('voice_transcripts').upsert({ source: source, message_id: mid, file_url: url, text: text }, { onConflict: 'source,message_id,file_url' }).then(function(){}).catch(function(){});
        } catch(e) {}
      } catch(e) {
        btn.innerHTML = origHtml;
        btn.disabled = false;
        toast((kk?'Мәтінге түрлендіру мүмкін болмады: ':'Не удалось расшифровать: ')+(e.message||e));
      }
    }
    // build 5.45: единый перехватчик клика по любой кнопке-скачиванию с
    // классом .dl-track-btn (фото — миниатюра/лайтбокс, файлы-документы)
    // — сначала проверяем личный/общий лимит скачивания (см.
    // _chatDownloadGate), и только если можно — запускаем настоящее
    // скачивание тем же способом, что и раньше (временная ссылка с
    // атрибутом download). Если сайт офлайн или пользователь не
    // авторизован — не блокируем, просто не считаем (как и раньше).
    // Слушаем на фазе ПОГРУЖЕНИЯ (capture=true) — у самих кнопок есть
    // свой inline onclick="event.stopPropagation()" (чтобы клик по
    // ⬇️ не выделял/не открывал сообщение целиком), который иначе не
    // пустил бы клик всплыть досюда; на погружении мы срабатываем раньше
    // него и сами решаем, продолжать действие по умолчанию или нет.
    document.addEventListener('click', function(ev) {
      var t = ev.target.closest && ev.target.closest('.dl-track-btn');
      if (!t) return;
      ev.preventDefault();
      ev.stopPropagation();
      var url = t.getAttribute('href');
      var dlName = t.getAttribute('download') || '';
      var bytes = parseInt(t.getAttribute('data-dl-bytes'), 10) || 0;
      function doDownload() {
        var a = document.createElement('a');
        a.href = url; a.download = dlName; a.target = '_blank'; a.rel = 'noopener';
        document.body.appendChild(a);
        a.click();
        a.remove();
      }
      var kkNow = state.settings && state.settings.lang === 'kk';
      var sb = (typeof getSb === 'function') ? getSb() : null;
      var sess = (typeof authSession === 'function') ? authSession() : null;
      if (!sb || !sess || !sess.userId || !bytes) { doDownload(); return; }
      _chatDownloadProceed(sb, sess.userId, bytes, kkNow, doDownload);
    }, true);
    // Автозагружаемые голосовые (<audio preload="none" data-dl-bytes>) —
    // реальная загрузка файла начинается в браузере в момент первого
    // нажатия ▶, то есть на событии 'play'. Оно не всплывает (bubbles:
    // false), поэтому слушаем на фазе погружения (capture=true) — так
    // делегированный обработчик всё равно сработает. dataset.dlCounted
    // защищает от повторного счёта при паузе/повторном воспроизведении
    // одного и того же плеера.
    document.addEventListener('play', function(ev) {
      var el = ev.target;
      if (!el || el.tagName !== 'AUDIO' || !el.hasAttribute('data-dl-bytes')) return;
      if (el.dataset.dlCounted === '1') return;
      var bytes = parseInt(el.getAttribute('data-dl-bytes'), 10) || 0;
      if (!bytes) return;
      el.dataset.dlCounted = '1'; // помечаем сразу, чтобы не запустить проверку дважды подряд
      var kkNow = state.settings && state.settings.lang === 'kk';
      var sb = (typeof getSb === 'function') ? getSb() : null;
      var sess = (typeof authSession === 'function') ? authSession() : null;
      if (!sb || !sess || !sess.userId) return;
      _chatDownloadGate(sb, sess.userId, bytes, kkNow).then(function(ok) {
        if (!ok) { try { el.pause(); el.currentTime = 0; } catch(e) {} return; }
        _downloadUsageRecord(sb, sess.userId, bytes);
      });
    }, true);
    // build 5.46→5.47: попытка считать автозагрузку миниатюр ФОТО в
    // лимите скачивания жила здесь как отдельный обработчик события
    // 'load' — но не умела отличить настоящую загрузку с сервера от
    // мгновенного показа уже закэшированной (IndexedDB, build 4.62)
    // картинки, и на каждый показ добавляла байты, даже если сеть вообще
    // не использовалась. В 5.47 эта логика перенесена туда, где она
    // технически точна — прямо в fetch()-ветку кэша картинок,
    // _chatImgSrcCached() выше по файлу (срабатывает только при
    // настоящем промахе кэша).
    document.addEventListener('click', function(ev) {
      var t = ev.target.closest && ev.target.closest('.voice-transcribe-btn');
      if (t) _voiceTranscribeFetch(t);
    });
    // build 4.100: клик по кнопке ручной загрузки голосового — подменяем
    // её на обычный плеер (тот самый <audio controls preload="none">,
    // что и при включённой автозагрузке), файл начинает грузиться только
    // теперь, не раньше.
    document.addEventListener('click', function(ev) {
      var t = ev.target.closest && ev.target.closest('.voice-manual-load-btn');
      if (!t) return;
      var url = t.getAttribute('data-url');
      var bytes = parseInt(t.getAttribute('data-dl-bytes'), 10) || 0;
      var wrap = t.parentElement;
      function doLoad() {
        var audio = document.createElement('audio');
        audio.controls = true; audio.preload = 'auto'; audio.src = url; audio.autoplay = true;
        audio.style.cssText = 'height:2.2rem;max-width:190px;flex:1';
        wrap.insertBefore(audio, t);
        t.remove();
      }
      var kkNow = state.settings && state.settings.lang === 'kk';
      var sb = (typeof getSb === 'function') ? getSb() : null;
      var sess = (typeof authSession === 'function') ? authSession() : null;
      if (!sb || !sess || !sess.userId || !bytes) { doLoad(); return; }
      _chatDownloadGate(sb, sess.userId, bytes, kkNow).then(function(ok) {
        if (!ok) return;
        doLoad();
        _downloadUsageRecord(sb, sess.userId, bytes);
      });
    });
    // build 4.97: меню выбора скорости воспроизведения голосового — вместо
    // прежнего переключения по кругу только между 1×/1.5×/2×, явный выбор
    // из шести вариантов (0.5×–2×), как попросил пользователь. Один
    // делегированный обработчик на весь документ — кнопки одинаковые везде
    // (общий чат/ЛС/группы), незачем плодить по слушателю на каждую.
    var VOICE_SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 2];
    function _closeVoiceSpeedMenu() {
      var ex = document.getElementById('voice-speed-menu');
      if (ex) ex.remove();
    }
    document.addEventListener('click', function(ev) {
      var btn = ev.target.closest && ev.target.closest('.voice-speed-btn');
      if (!btn) { _closeVoiceSpeedMenu(); return; }
      ev.stopPropagation();
      _closeVoiceSpeedMenu();
      var kkNow = state.settings && state.settings.lang === 'kk';
      var audio = btn.previousElementSibling;
      var curRate = parseFloat(btn.getAttribute('data-rate')) || 1;
      var menu = document.createElement('div');
      menu.id = 'voice-speed-menu';
      menu.style.cssText = 'position:fixed;z-index:10001;background:var(--bg-card);border:1px solid var(--border);border-radius:0.5rem;box-shadow:0 4px 16px rgba(0,0,0,0.4);padding:0.3rem;display:flex;flex-direction:column;min-width:4.5rem';
      menu.innerHTML = VOICE_SPEEDS.map(function(r) {
        var active = r === curRate;
        return '<button type="button" class="voice-speed-opt" data-rate="'+r+'" style="text-align:left;background:'+(active?'var(--accent)':'none')+';color:'+(active?'#04120c':'var(--text)')+';border:none;border-radius:0.35rem;padding:0.3rem 0.5rem;font-size:0.85rem;cursor:pointer">'+r+'× '+(r===1?(kkNow?'(әдепкі)':'(обычно)'):'')+'</button>';
      }).join('');
      document.body.appendChild(menu);
      var r = btn.getBoundingClientRect();
      var top = r.bottom + 4;
      if (top + menu.offsetHeight > window.innerHeight - 4) top = r.top - menu.offsetHeight - 4;
      var left = Math.min(r.left, window.innerWidth - menu.offsetWidth - 6);
      menu.style.top = Math.max(4, top) + 'px';
      menu.style.left = Math.max(4, left) + 'px';
      menu.querySelectorAll('.voice-speed-opt').forEach(function(opt) {
        opt.addEventListener('click', function(evOpt) {
          evOpt.stopPropagation();
          var rate = parseFloat(opt.getAttribute('data-rate'));
          if (audio) audio.playbackRate = rate;
          btn.setAttribute('data-rate', String(rate));
          btn.textContent = rate + '×';
          _closeVoiceSpeedMenu();
        });
      });
    });
    function openImgLightbox(url, bytes) {
      var ex = document.getElementById('img-lightbox');
      if (ex) ex.remove();
      var box = document.createElement('div');
      box.id = 'img-lightbox';
      box.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.9);z-index:10000;display:flex;align-items:center;justify-content:center;padding:1rem;cursor:zoom-out';
      var esc = _chatEsc(url);
      box.innerHTML = '<img src="' + esc + '" style="max-width:100%;max-height:100%;border-radius:0.5rem;object-fit:contain;cursor:default">' +
        '<a href="' + esc + '" download class="dl-track-btn" data-dl-bytes="'+(bytes||0)+'" target="_blank" rel="noopener" onclick="event.stopPropagation()" aria-label="download" style="position:absolute;top:0.8rem;right:3.4rem;background:rgba(255,255,255,0.15);color:#fff;border-radius:50%;width:2.2rem;height:2.2rem;display:flex;align-items:center;justify-content:center;font-size:1.1rem;text-decoration:none">⬇️</a>' +
        '<button type="button" id="img-lightbox-close" aria-label="close" style="position:absolute;top:0.8rem;right:0.8rem;background:rgba(255,255,255,0.15);color:#fff;border:none;border-radius:50%;width:2.2rem;height:2.2rem;font-size:1.2rem;cursor:pointer">✕</button>';
      document.body.appendChild(box);
      function close() { box.remove(); }
      box.addEventListener('click', function(ev) { if (ev.target === box) close(); });
      var closeBtn = document.getElementById('img-lightbox-close');
      if (closeBtn) closeBtn.addEventListener('click', close);
    }
    document.addEventListener('click', function(ev) {
      var t = ev.target.closest && ev.target.closest('[data-lightbox-src]');
      if (t) openImgLightbox(t.getAttribute('data-lightbox-src'), parseInt(t.getAttribute('data-dl-bytes'), 10) || 0);
    });

