    // «Смайлики», «Приветствия».
    var STICKER_SETS = {
      greet: { defs: GREET_STICKERS_DEFS, byId: GREET_STICKERS_BY_ID, icon: '\ud83d\udc4b', ru: 'Приветствия', kk: 'Сәлемдесу' },
      face: { defs: FACE_STICKERS_DEFS, byId: FACE_STICKERS_BY_ID, icon: '\ud83d\ude0a', ru: 'Смайлики', kk: 'Күлкіштер' },
      cat: { defs: CAT_STICKERS_DEFS, byId: CAT_STICKERS_BY_ID, icon: '\ud83d\udc3e', ru: 'Котики', kk: 'Мысықтар' }
    };
